(window.STORIES=window.STORIES||[]).push(...[{"n": 174, "l": "الجزء 148 | احداث السنه السابعه من الهجرة | طريقة تعامل رسول الله مع اخطاء زوجاته | الجزء الثاني", "u": "https://www.facebook.com/groups/710210019782034/permalink/836523780483990/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانية_وأربعون\n#أحداث_السنة_السابعة_من_الهجرة\n#طريقة_تعامل_رسول_الله_مع_أخطاء_زوجاته\n#الجزء_الثاني\nاتكلمنا المرة إللي فاتت عن تعامل رسول الله ﷺ مع بعض أخطاء زوجاته، وزي ما طلبتم هنكمل النهارده الكلام عن طريقة تعامل رسول الله ﷺ مع أخطاء زوجاته\n◇الموقف الخامس:\nالموقف الرابع إللي اتكلمنا عنه المرة إللي فاتت كان عن غيرة السيدة عائشة رضي الله عنها وشوفنا إن بسبب الغيرة دي هي وقعت في الخطأ، وشوفنا إزاي رسول الله ﷺ اتعامل مع الخطأ ده،\nالموقف إللي هنقوله دلوقتي برده عن غيرة السيدة عائشة، لكن رسول الله ﷺ اتعامل معاه بطريقة مختلفة، خلونا نشوف الموقف:\nالسيدة أم سلمة جاءت لرسول الله ﷺ ومعها صَحْفَةٍ فِيهَا طَعَامٌ حاجة زي طبق كده له ولأصحابه،\nوفي رواية تاني إن صفية رضي الله عنها هي إللي أرسلت الطبق إللي في طعام مع خادم لرسول الله ﷺ،\nالمهم إن في حد من زوجات رسول الله ﷺ أرسلت بطبق فيه طعام، واليوم ده كان يوم عائشة رضي الله عنها،\nفلما عائشة شافت الطبق غارت وضربت يد الخادم أو ضربت الطبق فوقع الطبق في الأرض انكسر والطعام اتكب على الأرض،\nرسول الله ﷺ بكل هدوء بدأ يلم الطعام إللي في الأرض ويقول : غارت أمكم...غارت أمكم!\nرسول الله ﷺ عذَر السيدة عائشة إنها عملت كده بسبب الغيرة، \nلكن الموقف بيقف عندنا هنا ونقول يا سلام شوفوا حلم رسول الله ﷺ وإن الموقف ده حصل قصاد الصحابة ومع ذلك رسول الله ﷺ لم يَصرخ ولم يشتم وراعى نفسية زوجته الغيور و....و.... كل الكلام ده حلو أوي\nلكن في نص تاني احنا مش بناخد بالنا منه، وهو تصحيح الخطأ نتيجة الغيرة\nالغيرة مش مُبرر أبدا للخطأ أو إن الشخص إللي بيغير ميتحملش نتيجة خطأه بسبب الغيرة دي،\nهنا حصل خطأ وهو كسر الإناء أو الطبق إللي كان فيه الطعام،\nورسول الله ﷺ عادل حكيم، فأخذ الطبق المكسور نصين وحاول إنه يجمعه في بعضه، يعني كأنه بيلزقه كده\n \nوأعطاه للسيدة عائشة لأنها هي إللي كسرته،\nوأخذ طبق السيدة عائشة السليم وأعطاه للي اتكسر طبقها، سواء بقى كانت السيدة أم سلمة أو السيدة صفية رضي الله عنهم أجمعين، وقال: طعام بطعام وإناء بإناء،\nففي نفس الوقت إللي رسول الله ﷺ عَذَر الغيرة إللي عند السيدة عائشة كذلك هو خلّاها تصلّح خطأها إللي حصل بسبب الغيرة،\nيعني رسول الله ﷺ بيعلمنا إن أه نُعذر الشخص لما يغير سواء كان رجل أو امرأة أو حتى طفل لكن مش معنى كده إنه لما يغلط بسبب الغيرة دي ويتعدّى حدوده يبقى نسكت ونُقره على غلطه ومنعالجش غلطه\nمادام أخطأ يبقى يتحمل نتيجة خطأه ويدفع ثمنه بحجم الخطأ ده،\nالسيدة عائشة رضي الله عنها كسرت الطبق فبقى من نصيبها، وطبقها السليم أُرسل للي اتكسر طبقها وهو ده العدل\nومحدش يقول طيب ما هو رسول الله ﷺ قال:\n《إن الْغَيْرَى لَا تُبْصِرُ أَسْفَلَ الْوَادِي مِنْ أَعْلَاهُ》\nهقولكم الحديث ده ضعيف لا يثبت عن رسول الله ﷺ أصلا\nولو فعلا الكلام ده صحيح مكنش رسول الله ﷺ عاتب السيدة عائشة ولَهَدَها في صدرها لما غارت وخرجت وراه زي ما حكينا المرة إللي فاتت،\nومكنش برده صلّح غلطها لما غارت وأعطاها هي الطبق المكسور وأخذ طبقها السليم،\nكان على الأقل يشتري طبق تاني بدل إللي اتكسر على أساس يعني إن السيدة عائشة غيرانة ومش واعية بقى بنفسها ولا باللي هي عملته\nفالغيرة مش مبرر للغلط ولا التعدي على حقوق الغير، لكن نلتمس العذر للغيران ونتعامل معاه بحكمة زي ما رسول الله ﷺ عمل عشان منزوّدش غيرته ونخليه يغلط بزيادة\n☆طبعا كل الكلام ده لا يَقدح ولا يُسِيء للسيدة عائشة إطلاقا،\nهي فقط بشر زي باقي البشر وهي مش معصومة فطبيعي جدا إن ممكن يحصل منها بعض الأخطاء، وربنا ارتضاها لرسوله زوجة في الدنيا والآخرة\nومادام الإنسان بصفة عامة بيعترف بخطأه وبيصلحه فدي حاجة متعيبوش أبدا، ورسول الله ﷺ نفسه قال :\n\"لا يَفْرَكْ مُؤْمِنٌ مُؤْمِنَةً إِنْ كَرِهَ مِنْهَا خُلُقًا، رَضِيَ مِنْهَا آخَرَ\"\nيعني مينفعش الرجل يكره زوجته بسبب إنه شايف فيها عيوب معينة مش عاجباه،\nلأنه لو كره فيها خُلق معين أكيد هيلاقي فيها خُلق تاني كويس،\nيعني مثلا ممكن واحدة تكون شَرِسة الخُلُق لكنها في نفس الوقت عفيفة وعندها دين فمفيش إنسان بريء من العيب\nوحديث رسول الله ﷺ  ده قاعدة عامة للكل، \nيعني سواء بين الزوج وزوجته أو الزوجة وزوجها أو بين الصاحب وصاحبه أو بين الآباء وأباءهم وهكذا،\nفزي ما في عيوب في مميزات، فلازم يكون في موازنة بين الاتنين\n◇الموقف السادس:\nبرده عن السيدة عائشة بس المرة دي الموضوع معكوس بقى، يعني هي إللي اتغار منها\nكان معروف بين الصحابة إن أحب الناس إلى رسول الله ﷺ هي عائشة رضي الله عنها،\nفكان الصحابة بيتحرّوا ليلة السيدة عائشة إللي رسول الله ﷺ هيكون فيها عندها ويرسلوا فيها الهدايا،\nوكان زوجات رسول الله ﷺ حزبين\nحزب فيه عائشة وحفصة وسودة وصفية،\nوالحزب الثاني كان فيه أم سلمة وباقي زوجات رسول الله ﷺ،\nفزوجات رسول الله ﷺ إللي في حزب أم سلمة اجتمعوا عند أم سلمة وقالوا لها إن الناس بيتحرّوا ليلة عائشة وبيرسلوا فيها الهدايا لرسول الله ﷺ،\nوطلبوا منها إنها تقول لرسول الله ﷺ إنه يأمر الناس إنهم يرسلوا الهدايا في أي ليلة مش لازم يعني ليلة عائشة بالذات،\nفلما كانت ليلة أم سلمة، وجاءها رسول الله ﷺ أخبرته بطلب أزواجه،\nفأعرض عنها رسول الله ﷺ ومردش عليها،\nفلما كانت المرة الثانية إللي عليها الدور فيها قالت له نفس طلب زوجاته،\nفرسول الله ﷺ برده أعرض عنها ومردش عليها، \nلما كانت المرة الثالثة وقالت له نفس الكلام رسول الله ﷺ قال لها:\n\"يا أم سلمة لا تُؤذِيني في عائشة فإنه والله ما نَزل عليّ الوحي وأنا في لِحاف امرأةٍ منكنّ غيرها\"\nفقالت أم سلمة رضي الله عنها:\nأتوب إلى الله تعالى من أذاك يا رسول الله!\nيعني تتوب وتستغفر من إنها تؤذي رسول الله ﷺ، لأن أذية رسول الله ﷺ لا تجوز، وربنا بيقول:\n\" وَالَّذِينَ يُؤْذُونَ رَسُولَ اللَّهِ لَهُمْ عَذَابٌ أَلِيمٌ \"\nفأم سلمة قالت لزوجات رسول الله ﷺ إللي حصل معاها، لكن المشكلة لسه قائمة، هم كمان عايزين من الهدايا إللي بتيجي لرسول الله ﷺ، ودي حاجة طبيعية عادي يعني\nطيب يعملوا إيه\nأرسلوا لفاطمة بنت رسول الله ﷺ وهي أحب بناته إليه ﷺ،\nوطلبوا منها إنها هي إللي تكلم رسول الله ﷺ،\nراحت فعلا فاطمة لرسول الله ﷺ وكانت مشيتها زي مشية رسول الله ﷺ بالضبط،\nفلما دخلت على رسول الله ﷺ بعد ما أَذِن لها بالدخول وكان الليلة دي عند عائشة، قالت لرسول الله ﷺ:\n\"إِنَّ أَزْوَاجَكَ أَرْسَلْنَنِي إِلَيْكَ يَسْأَلْنَكَ الْعَدْلَ فِي ابْنَةِ أَبِي قُحَافَةَ\"\nيعني بيطلبوا منه إنه يساوي بينهن في المحبة ودي حاجة قلبية محدش يقدر يتحكم فيها، \nرسول الله ﷺ كان بيحب عائشة أكثر منهن ولكنه ﷺ كان بيعدل في المعاملة بينهن والمبيت والأفعال وغيرها وطبعا مع موضوع الهدايا إللي احنا اتكلمنا عنه ده مع أم سلمة.\nعائشة رضي الله عنها سامعة وساكتة، وهي أصلا ملهاش دعوة بالحوار كله وملهاش ذنب في حاجة، مش هي إللي قالت للناس يعني والله يا جماعة أرسلوا الهدايا لرسول الله ﷺ في ليلتي\nالمهم،\nرسول الله ﷺ قال لفاطمة رضي الله عنها:\nأَيْ بُنَيَّةُ ، أَلَسْتِ تُحِبِّينَ مَا أُحِبُّ ؟\nيعني مش انتِ بتحبي إللي أنا بحبه،  فقالت له فاطمة:\n بَلَى !!\nفقال لها: فَأَحِبِّي هَذِهِ\nيعني هو بيقفل الموضوع بأسلوب لطيف، ففاطمة لما سمعته بيقول كده قامت ورجعت لزوجات رسول الله ﷺ إللي كانوا مجتمعين في بيت أم سلمة،\nفلما رجعت أخبرتهم باللي هي قالته وإللي رسول الله ﷺ قاله،\nفقالوا لها انتِ معملتيش حاجة، يعني لسه المشكلة متحلتش،\nفطلبوا منها إنها ترجع لرسول الله ﷺ مرة تانية وتكلمه لكن فاطمة رضي الله عنها رفضت وقالت:\nوَاللَّهِ لَا أُكَلِّمُهُ فِيهَا أَبَدًا\nزوجات رسول الله ﷺ شافوا بقى مين أحب زوجات رسول الله ﷺ له بعد عائشة، فأرسلوا زينب بنت جحش رضي الله عنها.\n☆والسيدة زينب كانت تُسامي السيدة عائشة في المنزلة عند رسول الله ﷺ، يعني هي ثاني أحب زوجات رسول الله ﷺ إليه،\nالسيدة عائشة بتقول عنها:\n\"لَمْ أَرَ امْرَأَةً قَطُّ خَيْرًا فِي الدِّينِ مِنْ زَيْنَبَ ، وَأَتْقَى لِلَّهِ، وَأَصْدَقَ حَدِيثًا ، وَأَوْصَلَ لِلرَّحِمِ ، وَأَعْظَمَ صَدَقَةً ،\nوَأَشَدَّ ابْتِذَالًا لِنَفْسِهَا فِي الْعَمَلِ الَّذِي تَصَدَّقُ بِهِ وَتَقَرَّبُ بِهِ إِلَى اللَّهِ تَعَالَى\"\nلكن مع كمال الأوصاف دي كان عندها شدة خُلُق وسرعة غضب، لكن برده لما كان بيحصل منها كده كانت بترجع بسرعة ومش بتصر على غضبها، وده كلام السيدة عائشة عنها:\n\"مَا عَدَا سَوْرَةً مِنْ حِدَّةٍ كَانَتْ فِيهَا، تُسْرِعُ مِنْهَا الْفَيْئَةَ\"\nاستأذنت زينب رضي الله عنها على رسول الله ﷺ فأذن لها رسول الله ﷺ ودخلت عليه وقالت له:\n\"يَا رَسُولَ اللَّهِ إِنَّ أَزْوَاجَكَ أَرْسَلْنَنِي إِلَيْكَ، يَسْأَلْنَكَ الْعَدْلَ فِي ابْنَةِ أَبِي قُحَافَةَ\"\nوبدأت زينب رضي الله عنها تتكلم وتُغلِظ في الكلام وصوتها بقى عالي وتطاولت على السيدة عائشة وسبّتها يعني شتمتها،\nكل ده ورسول الله ﷺ قاعد متكلمش\nفالسيدة عائشة بصت لوجه رسول الله ﷺ عايزة تعرف إذا كان يكره إنها ترد عليها ولّا لأ،\nفعرفت من وجهه إنه معندوش مشكلة إنها تنتصر لنفسها وترد، لكن طبعا مش معنى كده إن رسول الله ﷺ غمز لها مثلا أو أشار إليها إنها ترد،لأ ؛ لأن الأنبياء ليس لهم خائنة أعين،\nهي عرفت من تعابير وجهه ﷺ،\nفبدأت عائشة ترد عليها لحد ما أفحمتها وسكتتها،\nوهنا نظر رسول الله ﷺ لعائشة وتبسم وقال :\nإِنَّهَا ابْنَةُ أَبِي بَكْرٍ\nيعني هي شريفة وعاقلة وكاملة الفهم زي أبوها،\nوطبعا رسول الله ﷺ مدّخلش هنا لأنه عارف إن الغيرة هي سبب المشكلة، فهو سابهم يخلصوا أمورهم مع بعض وده من حكمته ﷺ،\nيعني هو بيتعامل مع كل موقف على حسب أحداثه، هو شاف إن ملوش لازمة إنه يدخل في الموقف ده،\nمع إنه كان لسه مدّخل من شوية لما فاطمة جاءت وعائشة متكلمتش، لكن هنا الموقف مختلف فسابهم بقى هم يحلّوا مشكلتهم بدون ما يُظهر ميله لأي طرف،\nوتخيلوا كده معايا لو كان رسول الله ﷺ تدَخّل في الموقف ده ودافع عن السيدة عائشة\n \nأكيد الغيرة هتزيد في قلب السيدة زينب وهي أصلا سريعة الغضب وبالتالي المشكلة هتكبر،\nمع إن من حق رسول الله ﷺ يدافع عن السيدة عائشة لأنها مظلومة في الموقف ده؛ لأن دي ليلتها وهي قاعدة معملتش حاجة وزينب رضي الله عنها هي إللي جاءت وابتدت المشكلة ووقعت في عائشة وسبّتها،\nلكن الحل الأمثل هنا إن رسول الله ﷺ ميدّخلش بينهم ويسيبهم همّ يصفّوا أمورهم مع بعض\n◇الموقف السابع والأخير:\nالموقف ده حصل متأخر شوية، يعني حصل في طريق رجوع رسول الله ﷺ مع نسائه من الحج في آخر السنة العاشرة من الهجرة، محصلش في السنة السابعة عشان بس محدش يتلغبط\nلما كان رسول الله ﷺ راجع للمدينة بعد الحج كانت صفية راكبة على جمل بطيء، فَأَبْطَأْت فِي الْمَسِيرِ، يعني اتأخرت عنهم في المشي، واليوم ده كان يومها، يعني كان الدور عليها إن رسول الله ﷺ يكون عندها، \nفاستقبلها رسول الله ﷺ وهي بتبكي وتقول له:\nحَمَلْتَنِي عَلَى بَعِيرٍ بَطِيءٍ؟!\nيعني انت خلتني أركب على جمل بطيء واتأخرت عنكم،\n\"فَجَعَلَ رَسُولُ اللهِ ﷺ يَمْسَحُ بِيَدَيْهِ عَيْنَيْهَا وُيُسْكِتُهَا\"\nيعني رسول الله ﷺ قعد يمسح دموعها ويهديها ويسكّتها،\nفالسيدة صفية أَبَتْ إِلَّا بُكَاءً، يعني صممّت على البكاء وزادت فيه\nواحنا كنا قلنا إنها كانت من النوع إللي بيبكي على طول\nتتوقعوا بقى رد فعل رسول الله ﷺ هنا كان إيه\nأظنكم هتقولوا أكيد رسول الله ﷺ الرحيم الصبور الحليم فضل يواسيها ويهدّيها أكتر \nلكن ده محصلش، رسول الله ﷺ غضب وسابها ومشي\n☆هو النساء بصفة عامة متخيلين إن زوجات رسول الله ﷺ مهما عملوا مع رسول الله ﷺ كان بيستحملهم عادي ومش بيغضب منهم وبيعمل لهم إللي هم عايزينه كله،\nوكل ما حد يكلمهم يقولوا ما تشوفوا رسول الله ﷺ كان بيعامل زوجاته إزاي وتشتكي إن زوجها مبيستحملهاش زي ما كان رسول الله ﷺ بيستحمل زوجاته،\nوفي نساء بتعمل زي السيدة صفية كده، يعني زوجها يراضيها ويقولها خلاص معلش وهي برده مصممة ومستمرة في العياط، ولما يغضب منها بسبب إنها ساقت فيها تقوم تزعل\nطيب يا جماعة هو احنا نشوف إللي لينا ونسيب إللي علينا\nأهه رسول الله ﷺ غضب من صفية وسابها ومشي لنفس السبب\n \nومش بس كده، ده هو حتى بعد كده مصالحهاش، ده هي إللي سَعَت في مصالحته\nيعني هي راحت للسيدة عائشة وقالت لها النهاردة يومي وأنا هدّيكي يومي ده هبة لو انتِ أرضيتي عني رسول الله ﷺ،\nيعني عايزاها تتوسط لها عند رسول الله ﷺ عشان يرضى عليها وميبقاش زعلان منها، تقول صفية:\n\"فَقَدِمَتْ ، فَأَتَتْ عَائِشَةَ فَقَالَتْ: يَوْمِي هَذَا لَكِ مِنْ رَسُولِ اللهِ ﷺ إِنْ أَنْتِ أَرْضَيْتِهِ عَنِّي\"\nفأخذت السيدة عائشة خمارها وكانت صبغته بوَرس وزعفران، ودي نباتات لها رائحة عطر، فنضحت عليه الماء، يعني رشت عليه الماء؛ لأن المية بتظهر الرائحة أكثر،\nفهي لما نضحت الماء على خمارها ريحة العطر ظهرت أكثر، وراحت لرسول الله ﷺ وقعدت عند رأسه،\nفاستغرب رسول الله ﷺ دخول السيدة عائشة عليه في يوم مش يومها وقال لها: مَا لَكِ؟\nيعني الليلة دي مش بتاعتك دي ليلة صفية، فقالت له عائشة رضي الله عنها: ذَلِكَ فَضْلُ اللهِ يُؤْتِيَهُ مَنْ يَشَاء\nوحكت له إللي حصل، فرضي رسول الله ﷺ عن صفية،\nلكن لسه مشكلة الجَمل بتاع صفية متحلتش، جملها بطيء\nورسول الله ﷺ عايز يحل المشكلة، فذهب للسيدة زينب بنت جحش وقال لها:\n\"إِنَّ صَفِيَّةَ قَدْ أَعْيَا بِهَا بَعِيرُهَا، فَمَا عَلَيْكِ أَنْ تُعْطِيَهَا بَعِيرَكِ؟\"\nيعني جمل صفية بطيء وهي اتأخرت عن المسِير بسببه، وطلب منها إنها تعطيها بعير من إللي عندها؛ لأن زينب كانت من أكثرهن ظهراً، يعني عندها أكثر من بعير،\nفهنا السيدة زينب رضي الله عنها قالت كلمة شديدة كلفتها كتير\nقالت:\nأَتَعْمَدُ إِلَى بَعِيرِي فَتُعْطِيَهُ الْيَهُودِيَّةَ؟!\nيعني انت عايز تاخد البعير بتاعي تديه لليهودية؟!!\nطبعا هي طعنت في السيدة صفية من ناحية النسب وإن أصلها من اليهود، ودي حاجة لا تعيبها أصلا فهي أم المؤمنين من ناحية الدين، \nتخيلوا رد فعل رسول الله ﷺ كان إيه بعد الكلمة دي\nرسول الله ﷺ مردش عليها وسابها ومشي وهَجَر السيدة زينب ثلاثة أشهر مقربش من بيتها\nاحنا كنا لسه قايلين إنها ثاني أحب زوجاته له ﷺ، \nوانتم شوفتم كل الصفات إللي السيدة عائشة قالتها عنها ومع ذلك وقع منها خطأ خلى رسول الله ﷺ يهجرها ثلاثة أشهر،\nهجرها باقي ذي الحجة ومحرم وصفر\nصالحها رسول الله ﷺ في بداية ربيع أول قبل ما يمرض مرض الموت، \nوكانت قبل ما يصالحها كانت عطّلت بيتها ونفسها حتى السرير أسندته إلى آخر البيت مبقاش له استعمال عندها ويأست من إن رسول الله ﷺ يأتيها،\n\"فَهَاجَرَهَا رَسُولُ اللهِ ﷺ وَسَلَّمَ ثَلَاثَةَ أَشْهُرٍ، فَلَمْ يَقْرَبْ بَيْتَهَا، وَعَطَّلَتْ زَيْنَبُ نَفْسَهَا، وَعَطَّلَتْ بَيْتَهَا، وَعَمَدَتْ إِلَى السَّرِيرِ فَأَسْنَدَتْهُ إِلَى مُؤَخَّرِ الْبَيْتِ، وَأَيَسَتْ مِنْ أَنْ يَأْتِيَهَا رَسُولُ اللهِ ﷺ\"\nفي بداية شهر ربيع الأول سمعت السيدة زينب صوت رسول الله ﷺ وهو داخل البيت، فدخل رسول الله ﷺ البيت ورجع السرير مكانه،\n\"فَبَيْنَا هِيَ ذَاتَ يَوْمٍ، إِذَا بِوَجْسِ رَسُولِ اللهِ ﷺ قَدْ دَخَلَ الْبَيْتَ ، فَوَضَعَ السَّرِيرَ مَوْضِعَهُ\"\nففرحت السيدة زينب طبعا وقالت لرسول الله ﷺ إن لها جارية طهُرت من الحيض اليوم وهي له، \nيعني هي أهدت لرسول الله ﷺ جاريتها، كنوع من الاسترضاء يعني، فدخل عليها رسول الله ﷺ ورضي عن زينب،\nوالجارية دي كانت آخر أمة تسرّى بها رسول الله ﷺ،\n فَقَالَتْ زَيْنَبُ: يَا رَسُولَ اللهِ جَارِيَتِي فُلَانَةُ قَدْ طَهُرَتْ مِنْ حَيْضَتِهَا الْيَوْمَ، هِيَ لَكَ؟ \nفَدَخَلَ عَلَيْهَا رَسُولُ اللهِ ﷺ وَرَضِيَ عَنْهَا\"\nفزي ما شوفتم كده رسول الله ﷺ أه رحيم وشفيق وحَسَن العِشرة ورفيق ورحيم بزوجاته وبيصبر عليهن، \nلكنه برده كان حَسَن التأديب، وكان بيرجع عن الغضب إلى الرضا وعن الإعراض إلى الإقبال بعد التعليم والتأديب؛\nزي ما شوفنا مع صفية وزينب رضي الله عنهما، فكان ﷺ بيجمع بين كمال الأدب وحُسْن الخُلق\nمش زي ما معظم النساء فاهمين إنه كان طيب وحنين على طول الخط ومش بيغضب خالص ولا بيعمل أي حاجة\n♡أتمنى إننا نكون اتعلمنا حاجة جديدة من خلال مواقف رسول الله ﷺ مع زوجاته ونحاول نطبق إللي اتعلمناه منه ﷺ\nإن شاء الله المرة الجاية هنرجع  نتكلم عن السرايا الأخيرة في السنة السابعة من الهجرة ونشوف تحقيق آخر شرط من صلح الحديبية"}, {"n": 175, "l": "الجزء 149 | احداث السنه السابعه من الهجرة | عمرة القضاء", "u": "https://www.facebook.com/groups/710210019782034/permalink/836523917150643/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وتسعة_وأربعون\n#أحداث_السنة_السابعة_من_الهجرة\n#عمرة_القضاء\nاتكلمنا قبل كده عن أربع سرايا أخرجهم رسول الله ﷺ بعد غزوة خيبر وكلها كانت متوجهة لقبائل غَطَفان، وقلنا إن رسول الله ﷺ أرسل لهم ست سرايا على مدار السنة، واحنا عرفنا أربعة واتبقى لنا اثنين،\n◇السرية الأولى:\nأخرجها رسول الله ﷺ في شهر شعبان إلى بني كِلاب من قبائل نجد وهي واحدة من فروع غطفان، وكانت السرية دي بقيادة أبو بكر الصديق رضي الله عنه، حصل قتال بين سرية المسلمين وبين بني كِلاب وانتصر المسلمون عليهم ورجعوا غانمين.\n◇السرية الثانية:\nهي سرية ابن أبي حَدرَد إلى رفاعة بن قيس،\nوالسرية دي على خلاف بين العلماء، هل كانت في السنة السابعة من الهجرة ولّا كانت في السنة الثامنة من الهجرة،\nعامة هي مش هتفرق كتير، إللي يهمنا الأحداث إللي حصلت فيها\nرفاعة بن قيس ده كان بيجمّع قبيلة قيس عشان يحاربوا رسول الله ﷺ، فوصل الخبر لرسول الله ﷺ، \nفأمر رسول الله ﷺ ابن أبي حَدرَد إنه يخرج مع رجلين من المسلمين ويستكشف الخبر، هل فعلا الكلام إللي وصله ده صحيح ولّا لأ،\nوقال له:\n\" اخرُجوا إلى هذا الرَّجل؛ حتى تأتونا به، أو تأتونا مِنه بخبرٍ وعِلم\"\nيعني إما تقتلوه أو تجيبوا لنا أخبار عنه، يعني زي ما بنقول كده بالعامية: يا تجيبولي خبره أو تجيبوا خبر عنه\nوقبل السرية دي بوقت قصير كان ابن حَدرَد قد تزوج، وكان أعطى زوجته مهر مائتي درهم،\nوانتم عارفين إن الصحابة كانوا فقراء فده يُعتبر مبلغ كبير بالنسبة لهم\nفراح ابن أبي حَدرَد لرسول الله ﷺ يطلب منه إنه يُعينه على سداد مهره، فرسول الله ﷺ سأله هو أعطاها مهر أد إيه، فقال له بن أبي حدرد إنه أعطاها مائتي درهم، \nفقال له رسول الله ﷺ:\n\"سبحان الله! لو كنتم تأخذون الدَّراهم من بطن وادٍ ما زدتم، والله ما عندي ما أعينك به\"\nيعني رسول الله ﷺ كأنه بيقول له: انتم لو بتلاقوا الفلوس دي في الشارع مكنتوش هتزودوا في المهور كده، يعني هو استكثر المهر وشافه إنه غالي، \nمش عارفة رسول الله ﷺ لو شاف حالنا دلوقتي هيقول إيه\nالمهم،\nهو قال له إنه معندوش أي حاجة يقدر يساعده بيها\nفبعد كم يوم جاء الخبر بقصة رفاعة بن قيس وإنه بيجهز لقتال المسلمين،\nفرسول الله ﷺ أمر ابن أبي حَدرَد إنه يخرج لعله يغنم منهم ويقدر يسد مهر المرأة إللي تزوجها،\nخرج ابن أبي حَدرَد مع رجلين من المسلمين وكان رسول الله ﷺ أعطاهم بعير يتعاقبوا عليه، يعني كل واحد يركب شوية،\nلكن البعير ده كان ضعيف جدا كان يادوب قادر يقوم ويتحرك\nوصل ابن أبي حَدرَد وصاحباه إلى منطقة \"الغابة\" مع غروب الشمس،\nفعمل كمين في ناحية وقال للرجلين إللي معاه: \n\"إذا سمعتماني قد كبَّرتُ، وشددتُ على العسكر، فكبِّرا وشدَّا معي؛ فوالله إنَّا لننتظر غرَّة القوم وأن نصيبَ منهم شيئًا\".\nيعني أول ما تسمعوا مني الله أكبر وتلاقوني هجمت على المعسكر فكبروا واهجموا معايا، احنا هنستنى بس إن القوم يكونوا في غفلة وساعتها هنقدر نغنم منهم\nوقعد ابن أبي حَدرَد في الكمين بتاعه لحد العشاء، وكان جيش \"رفاعة\" أَرسلوا واحد من الرعاة بتوعهم يعمل لهم حاجة،\nفلما اتأخر عليهم خافوا ليكون حصل له مكروه،\nفقام رفاعة بن قيس وعلّق سيفه في رقبته وقال إنه هيروح يدوّر على الراعي،\nفمجموعة من إللي معاه قالوا له خليك انت واحنا نروح ندور عليه، فقال لهم لأ محدش هيروح غيري، فقالوا خلاص نيجي معاك، فقال لهم :\n\"والله لا يتبعني أحد منكم.\"\nيعني محدش هيروح غيري\nفخرج \"رفاعة\" ومشي لحد ما عدى على كمين ابن أبي حدرد، فرماه ابن أبي حدرد بسهم فقتله، ورفاعة مطلعش صوت،\nسبحان الله، مشي لموته برجليه\nفبدأ ابن أبي حدرد بالتكبير فكبّر صاحباه وانطلقوا ناحية جيش المشركين فاترعب المشركون وطلعوا يجروا وأخذوا إللي يقدروا عليه من أبنائهم ونسائهم وما خفَّ من أموالهم،\nوتركوا وراءهم أغنام كثيرة وإبل عظيمة أخذها ابن ابي حدرد وصاحباه وانطلقوا بها للمدينة،\nدخلوا على رسول الله ﷺ يبشروه بمقتل رفاعة بن قيس وبهزيمة وفرار الجيش إللي كان مجمعه،\nوبالغنائم إللي جاءت من السرية دي استطاع رسول الله ﷺ إنه يُعين ابن أبي حدرد على سداد مهره\n☆ملحوظة في بعض الروايات بتقول إن ابن أبي حدرد قطع رأس رفاعة بن قيس وأتى بها لرسول الله ﷺ،\nلكن كل الروايات إللي بتقول كده ضعيفة أو مُنكرة ولا تصح،\nوأصلا قطع الرقبة من المُثْلة، ورسول الله ﷺ نهى عن المُثْلة، يعني نهى عن التمثيل بالجثث، فإزاي ابن أبي حدرد هيعصي أمر رسول الله ﷺ \nواحنا اتكلمنا بالتفصيل عن الموضوع ده في الجزء في الخامس والسبعين لو حابين ترجعوا له\nوبكده نقدر نوصف العام السابع الهجري بإنه كان عام دعوي جهادي، وصلت فيه الدعوة لكل مكان، وانتصر فيه المسلمون انتصار كبير على اليهود بصفة عامة،\nوانكمشت وخفَّت قوة غطفان بعد السرايا إللي أرسلها لهم رسول الله ﷺ،\nوزي ما بنقول ختامه مِسك، كان ختام السنة السابعة من الهجرة مِسك بالنسبة للصحابة، ففي شهر ذي القعدة حصل حدث أسعد رسول الله ﷺ والصحابة، وهو:\nدخول مكة لأداء العمرة\nوالعمرة دي اسمها عمرة القضاء، أو عمرة القضية أو عمرة الصُّلح،\nواسمها عمرة القضاء لأن رسول الله ﷺ قاضى عليها قريش، \nيعني حصلت بسبب المقاضاة أو المصالحة بين رسول الله ﷺ وقريش\nكنا قلنا إن من شروط صلح الحديبية إن المسلمين يرجعوا للمدينة من غير ما يعملوا العمرة، \nوبعدين يرجعوا السنة إللي بعدها إللي هي السنة السابعة للهجرة في شهر ذي القعدة يعملوا العمرة،\nفلما عدت السنة أعلن رسول الله ﷺ عن الخروج للعمرة وأمر إن محدش يتخلف من الصحابة إللي حضروا صلح الحديبية، وكانوا ألف واربعمائة،\nفبدأ الصحابة يتجهزوا للخروج للعمرة فاجتمع ألفان من الصحابة، غير النساء والأطفال وخرجوا بالسلاح الكامل الرماح والسيوف والسهام، كأنه مستعد للحرب،\nورسول الله ﷺ خرج بالسلاح الكامل ده مع إن الاتفاق في صلح الحديبية إن رسول الله ﷺ يدخل مكة بسلاح المسافر فقط؛ لأنه ﷺ لا يأمن غدر قريش\nيعني هو أخذ بالأسباب عشان يحمي المسلمين إللي معاه، ماهو ممكن قريش تغدر فجأة والمسلمين ساعتها هيكونوا في ورطة،\nلكنه في نفس الوقت ناوي يترك السلاح الكامل ده خارج مكة ويدخل مكة بسلاح المسافر عشان يوفي بعهده معاهم،\nفهو كده جمع بين الأمرين:\nالوفاء بالعهد وحماية المسلمين\nوصل رسول الله ﷺ والمسلمين معاه لذِي الحُلَيْفة إللي معروفة 《بأبيار علي》،\nوقعد يُلبي من ذي الحُلَيْفة لحد ما وصل لمكة المكرمة،\nودي كانت أول مرة رسول الله ﷺ والصحابة يدخلوا مكة بعد ما تركوها من سبع سنين\nاللحظة دي مهما قعدنا نتكلم أو نوصف فيها مش هنقدر نعبر عن مشاعر رسول الله ﷺ والصحابة\nفرق كبير جدا بين حال المسلمين من سبع سنين وحالهم دلوقتي،\nرسول الله ﷺ خرج وهو بيستخفي من قريش ويخفي آثار أقدامه وحريص إن محدش يشوفه،\nوالنهارده هو رجع لمكة و بيدخلها وأهل مكة كلهم شايفينه ومش قادرين يعملوا له حاجة،\nوداخلين مكة في مظاهرة إيمانية -إذا صح التعبير- وبيلبوا بكل عِزّة:\n 《لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك》\nالتلبية دي في الوقت ده الصحابة كانوا حاسينها أوي\nفعلا لا شريك لك، فعلا الحمد والنعمة والملك لك،\nحد من أهل مكة كان يصدق إن رسول الله ﷺ يوم ما خرج من مكة وهو مُطارد مطلوب للقتل إنه هيرجع ومعاه ألفين من الصحابة ومحدش هيقدر يمسهم بسوء وبيوسّعوا لهم الطريق عشان يقدروا يدخلوا ويسيبوا لهم مكة كلها عشان يؤدوا العمرة؟!!\nطبعا محدش كان تصور الكلام ده\n☆وما أشبه الليلة بالبارحة\nفي ناس كتير أوي مُطاردة برة بلادهم ومش قادرين يرجعوا بسبب الظلم والقهر، \nوإللي طاردوهم وظلموهم أو عايزين يقتلوهم برده مش متخيلين إن الناس دي ممكن ترجع في يوم من الأيام زي ما رسول الله ﷺ رجع،\nلكن لأن الملك لله فهييجي يوم وهيرجعوا وهتدور الدائرة،\nرسول الله ﷺ وهو رسول الله قعد سبع سنين ممكن إللي أقل منه يقعد أكتر فمفيش مشكلة\nنسأل مالك الملك أن يُرد كل غائب إلى أهله وبلده \nالمهم،\nبعض أهل مكة تركوا مكة للمسلمين وخرجوا للجبال المحيطة وقعدوا يتفرجوا على المسلمين وهم بيعملوا العمرة على طريقة المسلمين،\nوتخيلوا بقى حسرة المشركين وهم بيتفرجوا على المسلمين إللي كانوا بيعذبوهم من سبع سنين وهم في في داخل مكة بيؤدوا العمرة\nده غير بقى الانبهار إللي كان فيه أهل مكة لما شافوا قوة الصحابة وتجمعهم وثباتهم،\nورسول الله ﷺ نفسه كان حريص على إظهار قوة المسلمين،\nلأن في ناس كده؛ مش بتعترف إلا بقوة إللي قصادها\nعمل إيه بقى رسول الله ﷺ عشان يظهر قوة المسلمين\n◇أولا:\nقلنا إن رسول الله ﷺ جاء بالسلاح الكامل معاه من المدينة، \nفخلّى سرية من مائتين رجل من الصحابة موجودة خارج مكة ومعاها السلاح ده بقيادة محمد بن مسلمة، وهيعملوا تبادل بينهم وبين مائتين تانيين لما يخلصوا العمرة،\nوباقي الصحابة معاهم سلاح المسافر،\nطبعا كان في عيون لقريش-جواسيس يعني- بتراقب المسلمين، فلما شافوا السلاح الكامل مع الصحابة أرسلوا لرسول الله ﷺ وقالوا له الاتفاق بيننا إنك تيجي بسلاح المسافر، إيه بقى السلاح ده كله\nفرسول رسول الله ﷺ قال لهم إنه هيدخل مكة بسلاح المسافر، لكن طبعا لازم يوفر حماية لباقي المسلمين، لأنه لا يأمن على نفسه ولا على المسلمين من غدر قريش، \nوبكده يُلقي الرهبة في قلوب قريش\n◇ثانيا:\nرسول الله ﷺ دخل مكة وهو راكب على ناقته القصواء، والصحابة حوله محاوطينه ورافعين سيوفهم، والمنظر طبعا مَهيب\nوطبعا عشان يحموه من أي غدر ممكن يحصل له ﷺ\n◇ثالثا:\nدخل رسول الله ﷺ والصحابة وكلهم بيلبوا في صوت واحد،\nوتخيلوا بقى ألفين رجل داخلين بيلبوا في صوت واحد ورافعين صوتهم بالتلبية، وأهل مكة أول مرة يشوفوا منظر زي ده\n◇رابعا:\nعبد الله بن رواحة كان يتقدم صفوف المسلمين وهو ينشد الشعر، واختار من شعره إللي يناسب إظهار القوة، ومن الشعر إللي قاله:\nْخَلّوا بني الكفارَ عن سبِيلهْ*** خَلّوا فكل الخيرِ في رسولهْ\nاليوم نَضْربُكم على تَنزيلِهْ*** ضرباً يُزيلُ الهامَ عن مَقِيله\n                  ويُذْهلُ الخليلَ عن خلِيلِه\nودي حاجة ممكن نستغربها، واحد بينشد شعر في العمرة وفي الحرم وأمام رسول الله ﷺ \nحتى عمر بن الخطاب نفسه قال لعبد الله بن رواحة:\nوفي حرم الله تقول الشعر؟!!\nلكن رسول الله ﷺ أقرّ عبد الله بن رواحة، وقال لعمر :\n\"خلّ عنه يا عمر، فَلهيَ أسرع فيهم من نضْحِ النّبل\"\nيعني الأبيات أسرع في قريش من رمي السهام، والشعر كان وسيلة الإعلام الأولى عند العرب، يعني لما يتقال الشعر  الكل بيقف ويستمع له، \nفكان كلام ابن روحة من أقوى الأسلحة إللي اتوجهت لقريش\n◇خامساً:\nرسول الله ﷺ صلى بالمسلمين الصلوات الخمس في الأيام الثلاثة بصورة جماعية في الحرم، \nوتصوروا كده صلاة ألفين من الرجال غير النساء والصبيان بطريقة واحدة ...بتكبير وتحميد، وبقيادة منظمة من رسول الله ﷺ \nزي ما بنشوف كده في التليفزيون المسلمين لما بيصلوا عند الكعبة منظرهم بيكون رهيب، مع إننا ممكن نكون شوفناه كذا مرة لكن الإحساس هو هو\nأهل مكة بقى أول مرة يشوفوا التجمع الكبير ده في الحرم وبالصورة دي، فكانوا منبهرين من المنظر وقوة المسلمين ظاهرة\n◇سادسا:\nأمر رسول الله ﷺ أصحابه أن يَرْمَلوا في الأشواطِ الثلاثة،\nوالرّمَل معناه المشي السريع مع تقارب الخطوات، وقال للصحابة:\n\"رحم الله امرأً أراهم اليوم من نفسه قوة\"\nلأن المشركين كانوا أطلقوا إشاعة إن المسلمين أضعفتهم حمى يثرب، يعني بسبب إنهم هاجروا للمدينة وحصلت لهم حُمّى فبقى جسمهم ضعيف،\nفكشف رسول الله ﷺ عن كتفه الأيمن وأمر الصحابة بالرّمل عشان يورّوا المشركين قوتهم،\nولما المشركين شافوا المسلمين كده قالوا هم دول إللي بتقولوا عليهم الحمى أضعفتهم دول أقوى من كذا وكذا\n◇سابعا:\nتعامُل الصحابة مع الرسول ﷺ أمام المشركين\nقبل كده عروة بن مسعود الثقفي كان حكى لهم عن توقير الصحابة لرسول الله ﷺ وطاعتهم لهم،\nدلوقتي بقى هم شايفين بعنيهم الكلام ده، فتأكدوا إن الصف الإسلامي صف واحد قوي الكل بيسمع ويطيع لزعيم واحد هو رسول الله ﷺ \nرسول الله ﷺ قعد في مكة ثلاثة أيام، بعد ما أدى العمرة تزوج رسول الله ﷺ من آخر زوجاته وهي السيدة ميمونة بنت الحارث إللي هنعرف قصة زواجها من رسول الله ﷺ المرة الجاية إن شاء الله"}, {"n": 176, "l": "الجزء 150 | احداث السنه السابعه من الهجرة | زواج رسول الله من ميمونه | المرأه التي وهبت نفسها للنبي", "u": "https://www.facebook.com/groups/710210019782034/permalink/836524083817293/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وخمسون\n#أحداث_السنة_السابعة_من_الهجرة\n#زواج_رسول_الله_من_ميمونة\n#المرأة_التي_وهبت_نفسها_للنبي\nاتكلمنا المرة إللي فاتت عن عمرة القضاء ووقفنا عند زواج رسول الله ﷺ من آخر زوجاته وهي السيدة ميمونة بنت الحارث الهِلالية العامرية، \nوالسيدة ميمونة تبقى خالة خالد بن الوليد وهي أخت الصحابية أسماء بنت عميس البحرية زوجة جعفر بن أبي طالب إللي حكينا عن قصتها مع عمر بن الخطاب بعد فتح خيبر لو تفتكروا\nوالسيدة ميمونة برده هي أخت أم المؤمنين زينب بنت خزيمة إللي تزوجت رسول الله ﷺ وماتت بعد زواجها بحوالي ثمانية أشهر، وهي أخت سلمى بنت عميس زوجة حمزة بن عبد المطلب رضي الله عنه،\nوهي أخت أم الفضل زوجة العباس عم رسول الله ﷺ،\nهم كلهم أخوات من أم واحدة، \nويقال عن أمهم إنها أكرم عجوز في الأرض أصهاراً، يعني تخيلوا كده لما واحدة يكون زوج بنتين من بناتها رسول الله ﷺ، وزوج الثالثة سيد الشهداء حمزة،\nوزوج الرابعة جعفر بن أبي طالب ابن عم رسول الله ﷺ وإللي هيكون لقبه الطيار وهنعرف بعدين ليه، \nوزوج الخامسة عم رسول الله ﷺ، فهل في شرف أعظم من كده\nورسول الله ﷺ قال عن الأخوات دول:\n\" الأَخَوَاتُ مُؤْمِنَاتٌ: مَيْمُونَةُ زَوْجُ النَّبِيِّ، وَأُمُّ الْفَضْلِ بنتُ الْحَارِثِ، وسَلْمَى امْرَأَةُ حَمْزَةَ، وَأَسْمَاءُ بنتُ عُمَيْسٍ هِيَ أُخْتُهُنَّ لأُمِّهِنَّ\"\nيعني رسول الله ﷺ شَهد للسيدة ميمونة وأخواتها بحقيقة الإيمان واستقراره في قلوبهن، وده فضل عظيم لهن رضي الله عنهن وأرضاهن.\nوالسيدة ميمونة من قبيلة بني هلال بن عامر العزيزة جداً، فقبيلة بني عامر دي كانت بتفتخر على العرب إنها من القبائل إللي لم يُسبَ منها امرأة واحدة ولم يُؤخذ منها أسير، يعني قبيلة قوية جدا،\nفزواج رسول الله ﷺ من ميمونة هو إعلان ارتباط بين رسول الله ﷺ وبين قبيلة قوية عن طريق النسب، وبكده تتناقص الأرض من حول المشركين، \nده غير إن رسول الله ﷺ كان عايز يؤلّف قلوب بني هلال إللي هم قبيلة السيدة ميمونة عشان يشجعهم على الدخول في الإسلام،\nوفعلا ده إللي حصل بعدين، بدأوا يدخلوا في الإسلام ورا بعض ورسول الله ﷺ لقى منهم العطف والتأييد المطلق له\nالسيدة ميمونة كانت متزوجة قبل رسول الله ﷺ مرتين، زوجها الأول طلقها، وزوجها الثاني مات عنها،\nفجعلت أمرها لأختها أم الفضل زوجة العباس، يعني كأنها قالت لها زي ما بنقول كده شوفي انتِ ناوية تعملي إيه وأنا راضية بكل إللي تقولي عليه وتعمليه،\nفأم الفضل جعلت أمر أختها ميمونة للعباس، فعرضها العباس على رسول الله ﷺ فتزوجها رسول الله ﷺ وأصدقها أربعمائة درهم عن رسول الله ﷺ،\nيعني دفع لها مهر أربعمائة درهم بالنيابة عن رسول الله ﷺ، وكان ساعتها عمرها إما في أواخر العشرينات أو منتصف الثلاثينات على حسب اختلاف الروايات،\nطبعا الزواج كان بعد ما رسول الله ﷺ تحلّل من الإحرام\nوالسيدة ميمونة كان اسمها بَرّة فغيّره رسول الله ﷺ وسماها ميمونة،\nبعد ما خلصت الثلاثة الأيام المُتفق عليها بين رسول الله ﷺ والمشركين في صلح الحديبية؛ رسول الله ﷺ كان عايز يستغل زواجه بإنه يطوّل مدة إقامته في مكة أكثر كوسيلة يعني لزيادة التفاهم بينه وبين قريش،\nلكن جاءه سهيل بن عمرو ومعاه مجموعة من قريش وقالوا له إنه خلاص وقتك خلص فاخرج من مكة،\nفرسول الله ﷺ قال له:\n\"وما عليكم لو تركتموني، فأعْرست بين أظهركم، وصنعنا لكم طعاماً، فحضرتموه\"\nيعني بيقول لهم مفيش مشكلة لو سيبتوني أدخل على زوجتي وأعمل لكم وليمة عرس وتحضروها،\nفقالوا له:\n لا حاجة لنا في طعامك، فاخرج عنا \nيعني احنا مش عايزين منك أكل، خلاص خلّصت العمرة امشي بقى،\nفخرج رسول الله ﷺ والصحابة من مكة لحد ما وصلوا عند مكان اسمه سَرِف، \nوهي منطقة قريبة من التّنْعِيم، وأتى أبو رافع مولى رسول الله ﷺ بميمونة لأن رسول الله ﷺ كان وكّله في تزويجه بميمونة، \nفتزوجها رسول الله ﷺ ودخل بها ﷺ هناك، \nوالمكان إللي اسمه سَرِف ده بين مكة والمدينة هو المكان إللي ماتت فيه السيدة ميمونة بعدين لما كانت راجعة من الحج في خلافة معاوية بن أبي سفيان رضي الله عنه،\nوهي آخر واحدة ماتت من أزواج النبي ﷺ، فمكان عُرسها هو مكان وفاتها\nوبكده اكتمل عدد زوجات رسول الله ﷺ التسعة وهن:\n♡سودة بنت زمعة\n♡عائشة بنت أبي بكر\n♡حفصة بنت عمر\n♡جُوَيرية بنت الحارث\n♡أم سلمة هند بنت أبي أمية\n♡زينب بنت جحش\n♡أم حبيبة رملة بنت أبي سفيان\n♡صفية بنت حيي بن أخطب\n♡ميمونة بنت الحارث\nوخديجة بنت خويلد وزينب بنت خزيمة، والاتنين دول ماتوا في حياة رسول الله ﷺ، رضي الله عنهن أجمعين\n☆ملحوظة:\nفي بعض الروايات بتقول إن السيدة ميمونة هي المرأة المؤمنة التي وهبت نفسها للنبي، \nوهي إللي نزلت فيها الآية :\n\"وَامْرَأَةً مُؤْمِنَةً إِنْ وَهَبَتْ نَفْسَهَا لِلنَّبِيِّ إِنْ أَرَادَ النَّبِيُّ أَنْ يَسْتَنْكِحَهَا خَالِصَةً لَكَ مِنْ دُونِ الْمُؤْمِنِينَ\"\nلكن مفيش ولا رواية صحيحة بتقول كده،\nأنا بحثت ودوّرت لقيت إن الخبر مذكور بصيغة المجهول : 《يُقال》 إن السيدة ميمونة هي التي نزلت فيها الآية دي،\nفعامةً يعني، في أكثر من امرأة وهبت نفسها للنبي وبعض قصص النساء دول موجودة في أحاديث صحيحة،\nفاللي يهمنا احنا نستفيد إيه من الآية ونفهم الحكم الشرعي منها\nخلونا نشوف معنى الهبة في الآية، الهبة:\nهو إن الرجل يتزوج المرأة لكن بدون مهر، يعني زواج عادي جدا بالشهود والإشهار وكل حاجة لكن بدون مهر،\nمش زي ما في ناس فاهمة غلط وإن الهبة هنا يعني المرأة تعطي الرجل نفسها بدون زواج، ده كده زنى\nوهبة المرأة نفسها لرسول الله ﷺ يعني إنه يتزوجها بدون مهر ،دي حالة خاصة برسول الله ﷺ فقط مش لأي حد من أمته\n\"خَالِصَةً لَكَ مِنْ دُونِ الْمُؤْمِنِينَ\"\nكده فهمنا معنى الآية، خلونا بقى نشوف قصة امرأة من النساء اللائي وهبن أنفسهن لرسول الله ﷺ وقصتها موجودة في البخاري ومسلم، \nواحد من الصحابة اسمه سهل بن سعد بيحكي القصة وبيقول إن في امرأة جاءت لرسول الله ﷺ في المسجد وقالت له: \n\"يَا رَسُولَ اللَّهِ! جِئْتُ لِأَهَبَ لَكَ نَفْسِي\" \nيعني عايزاك تتزوجني وأنا متنازلة عن مهري، هي عايزة تاخد شرف إنها تكون زوجة رسول الله ﷺ،\nفرسول الله نظر إليها \"فَصَعَّدَ النَّظَرَ إِلَيْهَا وَصَوَّبَهُ\"\nيعني دقق فيها النظر، وده جائز شرعا لأن المرأة هنا في حالة الخطبة ويجوز النظر والتمعّن في وجه المخطوبة بغرض الزواج ورسول الله ﷺ كان ناوي يتزوجها لو حس برغبة في الزواج منها،\nفبعد ما نظر إليها طَأْطَأَ رَأْسَهُ، يعني وطى راسه وغض بصره عنها وسكت، لعلها تفهم إنه خلاص مش عايزها،\nوهو مصرحش بالرفض ويقولها أنا مش عايزِك، أو مليش فيكِ رغبة، عشان محبش إنه يحرجها لأنه ﷺ كان شديد الحياء،\nومكنش بيحب يحرج حد،\nفالمرأة لما شافت إن رسول الله ﷺ لَمْ يَقْضِ فِيهَا شَيْئًا جَلَسَتْ، يعني قعدت لما لقت إن رسول الله ﷺ مردش عليها برفض ولا قبول وهي مكنتش فهمت مقصد رسول الله ﷺ،\nوفي رواية إنها قامت تاني وعرضت نفسها على رسول الله ﷺ ورسول الله ﷺ مردش عليها وقعدت وقامت مرة ثالثة فساعتها رسول الله ﷺ قال لها إنه لا حاجة له في الزواج،\n☆طيب وهو رسول الله ﷺ رفضها ليه\nلأنه لم يرغب فيها، ومش عايزها زوجة له، فمش كل خاطب نظر لمخطوبة وتأملها يبقى لازم يتزوجها\nالنظر أصلا ربنا شَرعه بين الخاطب والمخطوبة عشان يقرر إذا كان هيتزوجها ولّا لأ،\nوالموضوع مش موضوع جمال، ممكن المرأة تكون جميلة والخاطب يَعرض عنها ويرفضها، \nالمسألة مسألة اطمئنان نَفس وقَبُول، وممكن برده يكون الرجل على خلق ودين والمرأة ترفضه بسبب إن مفيش بينهم قَبُول\nفاللي يحدد الرفض أو الموافقة هو النظر بين الخاطب والمخطوبة،\nودي رسالة للبنات إللي لابسين نقاب وبيكونوا متضايقين وزعلانين إن الخاطب ييجي يشوفهم ويمشي من غير ما الزواج يتم، \nوساعات بعض البنات ميرضوش يقلعوا النقاب أصلا عشان الخاطب يشوف وجهها\nيعني انتم شوفتم إللي أحسن مننا كلنا كشفت عن وجهها لرسول الله ﷺ ورآها رسول الله ﷺ ورفضها، \nومعلش يعني رفض رسول الله ﷺ لها مش زي رفض أي حد تاني، ومع ذلك الدنيا مشيت عادي جدا وتزوجت في نفس المجلس من واحد تاني\nواحد من الصحابة إللي كانوا موجودين لما لقى إن رسول الله ﷺ ملوش رغبة في الزواج منها قال له :\n\"يَا رَسُولَ اللَّهِ! إِنْ لَمْ يَكُنْ لَكَ بِهَا حَاجَةٌ فَزَوِّجْنِيهَا\"\nيعني يا رسول الله لو انت مش عايز تتزوجها فخليني أنا أتزوجها.\n☆ ممكن حد يسأل ويقول طيب مش الحديث ده كده ممكن نستدل بيه على إن النساء كانوا كاشفين وجوههن\nلا يصح الاستدلال بالحادثة دي على كشف النساء لوجوههن\n ليه\nلأن المرأة لما جاءت كاشفة عن وجهها كان لإرادة تزوُّج النبي ﷺ بها، \nيعني هي عايزاه يشوف وجهها عشان يحدد يقبل بها ولّا ولأ، والنظر للمخطوبة مفيهوش مشكلة زي ما قلنا، بالعكس ده شريعة الإسلام بتأمر بإن الخاطب ينظر للمخطوبة\nوطبعا نفس الكلام هنقوله على الصحابي، \nفالصحابي هو كمان نظر إليها عشان يخطبها فلما عجبته، قال لرسول الله ﷺ إنه عايز يتزوجها،\nفالحوار هنا كله هو نظر خاطب لمخطوبة، عشان كده كانت كاشفة وجهها، ورسول الله ﷺ مأنكرش عليها وقال لها إن إللي عملته ده مينفعش سواء في موضوع الهبة أو موضوع إنها تكشف وجهها أمام الخاطب\nده غير طبعا الأدلة على تغطية الوجه كثيرة، فبأي حال من الأحوال مينفعش حد يستدل بالحادثة دي على إن النساء كانوا كاشفين وجوههن\nلما الصحابي بقى طلب من رسول الله ﷺ إنه يزوّجه المرأة،  استأذنها رسول الله ﷺ إذا كانت راضية بالصحابي كزوج فوافقت، فسأل رسول الله ﷺ الصحابي :\n\"هَلْ عِنْدَكَ مِنْ شَيْءٍ\"\nيعني رسول الله ﷺ بيسأله عن حاجة يقدمها للمرأة كمهر، \nفقال له الصحابي: لا والله يا رسول الله \nفقال له رسول الله ﷺ إنه يروح بيته كده ويبحث يمكن يلاقي حاجة تنفع مهر، فراح الصحابي لبيته وبحث ملقاش حاجة ورجع لرسول الله ﷺ وقال له إنه ملقاش حاجة،\nفقال له رسول الله ﷺ:\n\"انْظُرْ وَلَوْ خَاتَمًا مِنْ حَدِيدٍ\"\nيعني روح شوف ولو حتى خاتم من حديد، فراح الرجل لبيته تاني وبحث ورجع لرسول الله ﷺ وقال له إنه ملقاش حتى خاتم من حديد،\nوعرض الصحابي على رسول الله ﷺ إنه يعطي المرأة نص الرداء إللي كان لابسه،\nفرسول الله قال له:\n\"مَا تَصْنَعُ بِإِزَارِكَ، إِنْ لَبِسْتَهُ لَمْ يَكُنْ عَلَيْهَا مِنْهُ شَيْءٌ ، وَإِنْ لَبِسَتْهُ لَمْ يَكُنْ عَلَيْكَ شَيْءٌ ؟!\"\nيعني هي هتعمل بيه، لو هي أخذته ملوش فايدة سواء ليك أو لها،\nفالصحابي لما لقى الموضوع اتقفل ومش معاه أي حاجة يدفعها مهر راح قاعد، وقعد وقت طويل في المجلس وبعدين قام،\nفلما شافه رسول الله ﷺ ماشي أمر حد ينده له فجاء لرسول الله ﷺ، فقال له رسول الله ﷺ:\nمَاذَا مَعَكَ مِنَ القُرْآنِ؟ \nيعني انت حافظ كم سورة من القرآن، قال:\nمَعِي سُورَةُ كَذَا، وَسُورَةُ كَذَا، وَسُورَةُ كَذَا، وقعد يعد السور إللي حافظها،\nفقال له رسول الله ﷺ:\nأَتَقْرَؤُهُنَّ عَنْ ظَهْرِ قَلْبِكَ ؟\nيعني انت حافظهم زي اسمك كده، فقال له الصحابي: نعم\nفقال له رسول الله ﷺ:\n\"اذْهَبْ فَقَدْ مَلَّكْتُكَهَا بِمَا مَعَكَ مِنَ القُرْآن\"\nيعني أنا زوّجتك المرأة دي باللي معاك من القرآن، وطبعا الصحابة كانوا بيطبقوا إللي حافظينه من القرآن،\nمش زي ما بنشوف دلوقتي للأسف بعض الناس يبقوا\nحافظين القرآن كله ومفيش لا أخلاق ولا التزام بالدين ولا أي حاجة\nالمهم،\nكده احنا عرفنا معنى الهبة وقصة المرأة الواهبة، فاضل تعليق السيدة عائشة على الموضوع\nالسيدة عائشة كانت تُعيّر النساء اللائي وهبن أنفسهن لرسول الله ﷺ وتقول:\nألا تستحي المرأة أن تَعرِض نفسها بغيرِ صداق؟!!\nيعني هي شايفة إن من العار إن المرأة تتزوج زواج صحيح بوليّ وشهود لكنها تتنازل عن مهرها،\nأنا مش عارف السيدة عائشة لو شافت مجتمعنا وإللي البنات بيعملوه دلوقتي هتقول إيه\nربنا يصلح حال الجميع\nفلما ربنا أنزل :\n\" تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ\"\nالسيدة عائشة قالت:\n《 ما أُرَى رَبَّكَ إلَّا يُسَارِعُ في هَوَاكَ》\nوهنا محتاجين نقف وقفة عشان نوضح كم نقطة كده، لأن الكلام في شبهة، وفي ناس أخذت الكلام ده وهو في صحيح البخاري وبدأت تطعن على رسول الله ﷺ وعلى السيدة عائشة\n◇أولا خلّونا نفهم معنى الآية:\nالآية معناها حاجتين:\n☆الأول:\nإن مفيش حرج على رسول الله ﷺ إنه لا يعدل بين نساءه ويقدر يبيت عند من يشاء ويترك من يشاء،\nيعني رسول الله ﷺ غير مُلزم بالعدل بينهن ولا يُحاسب على كده، ودي حاجة خاصة برسول الله ﷺ، لكن مع ذلك رسول الله ﷺ من حُسن خلقه إنه كان بيعدل بينهن\n☆الثاني:\nإن ربنا بيخيّر رسول الله ﷺ إما إنه يتزوج الواهبات أنفسهن له كلهن أو بعضهن ويترك الباقي،\nوحتى برده له الاختيار إنه لو رفض واحدة ممكن يرجع في كلامه بعدين ويتزوجها،\nواحنا عارفين إن رسول الله ﷺ لا ينطق عن الهوى، وكل أفعاله وحي من عند الله حتى زواجه،\nفربنا بقى جعل الاختيار في موضوع الهبة لرسول الله ﷺ بدون إلزام منه سبحانه.\nبكده بقى الاختيار كله لرسول الله ﷺ، عشان كده السيدة عائشة قالت :\"ما أُرَى رَبَّكَ إلَّا يُسَارِعُ في هَوَاكَ\"\nومعنى الكلام:\n\"ما أرى الله إلا مُوجداً لما تريد بلا تأخير، مُنزِلاً لما تحب وتختار\"\nيعني أنا مش شايف غير إن ربنا بيحقق لك إللي انت عايزه وبتحبه بدون تأخير،\nولو انها قالت في مرضاتك لكان أفضل وأحسن لأن رسول الله ﷺ لا ينطق عن الهوى،\nفهي قالت الكلمة دي من باب الدلال والغيرة على رسول الله ﷺ، \nوقلنا قبل كده إن رسول الله ﷺ كان بيعذر غيرتها، وطبعا لو كان في خطأ كان رسول الله ﷺ صححه لها\nفرسول الله ﷺ فهم مقصد عائشة من الكلام وإنها لا تقصد الهوى بالمعنى المذموم ولكنها تقصد الرغبة والاختيار.\nعارفين المعنى إللي تقصده السيدة عائشة زي إيه تقريبا\nزي تغيير القبلة كده،\nرسول الله ﷺ لما كان في المدينة كان عايز يصلي ناحية المسجد الحرام، فربنا لما غيّر القبلة لحكمته وافق تغيير القبلة\n《هوى عند رسول الله ﷺ》 أو خلينا بقى نقول الكلمة الصحيحة وهي 《رغبة رسول الله ﷺ》 في إنه يصلي ناحية البيت الحرام\nيبقى خلاصة الكلام إن السيدة عائشة لم تقصد اتهام رسول الله ﷺ باتباع الهوى، ولا إن الدين ماشي على هوى رسول الله ﷺ، وإن ربنا بيعمل له إللي هو عايزه كده وخلاص بدون أي حكمة والعياذ بالله زي ما في ناس بتقول\nنرجع بقى لرسول الله ﷺ لما كان خارج من مكة بعد انتهاء الثلاثة أيام\nلما كان ﷺ خارج من مكة سمع حد بينادي عليه ويقول :\nياعم! يا عم!\nفلقوا إللي بينادي هي ابنة حمزة رضي الله عنه كانت عايزة تمشي معاهم وتهاجر للمدينة وكان اسمها أُمامة،\nفأخذ بيدها علي بن أبي طالب رضي الله عنه وأعطاها لفاطمة وقال لها خذيها، يعني على أساس إنها تعيش معاهم،\nفجاء جعفر بن أبي طالب وقال إن هو إللي هيأخذها،\nفقال له علي:\n\"أنَا أحَقُّ بهَا وهي ابْنَةُ عَمِّي\"\nفجعفر أخو علي قال له: \n\"ابْنَةُ عَمِّي وخَالَتُهَا تَحْتِي\"\nيعني أنا أحق بيها لأن خالتها تبقى زوجتي، وهي بنت عمي زيي زيك،\nفجاء زيد بن حارثة وقال إن هو إللي أحق بيها منهم لأن أبوها حمزة يبقى أخوه، \nآخى بينهما رسول الله ﷺ بعد الهجرة وقلنا في الجزء الخمسين إن الأخوة دي زي أخوة النسب كده،\nفبقى الثلاثة دلوقتي مختصمين في مين إللي يأخذ بنت حمزة يرعاها عنده\nفحكم بينهم رسول الله ﷺ وقال إن إللي أحق بها هو جعفر رضي الله عنه لأن خالتها زوجته والخالة في منزلة الأم،\nوفي شريعة الإسلام بصفة عامة الخالة تُقدم على العمة في حضانة الطفل، \nلأن صفية بنت عبد المطلب أخت حمزة كانت موجودة، ومع ذلك رسول الله ﷺ حكم بالحضانة لخالتها أسماء بنت عُميس،\nطبعا لو في موانع أو في أسباب تمنع الموضوع ده فالقاضي بقى هو إللي يحدد مين الأُوْلى بالحضانة، لكن الكلام هنا بصفة عامة\nفاللي أخذ أُمامة بنت حمزة هو جعفر رضي الله عنه \nوقال رسول الله ﷺ لعلي بن أبي طالب: أنتَ مِنِّي وأنا منك! أنت مني يعني في النسب والمحبة والأسبقية للإسلام وغيرها من الفضائل،\nوقال لجعفر:\nأشبَهتَ خَلْقي، وخُلُقي!\nيعني انت تشبهني في الشكل وفي الأخلاق والفضائل، \nوقال لزيد بن حارثة:\nأنْتَ أخونا ومَوْلانا!\nيعني أخونا في الإسلام وعتيقنا، ومولانا جاية من الولاء وهي رابطة بين العبد إللي كان مملوك وأعتقه سيده زي علاقة النسب بين الأقارب كده، فالمقصود إن العلاقة بينهم علاقة قوية\nوعرض علي بن أبي طالب على رسول الله ﷺ إنه يتزوج بنت حمزة رضي الله عنه لكن رسول الله ﷺ قال له إنها تبقى ابنة أخوه من الرضاعة،\nلأن رسول الله ﷺ لما اتولد أرضعته ثُوَيبة جارية أبي لهب وكانت أرضعت حمزة قبله وبكده بقوا هم الاتنين إخوة من الرضاع،\nويَحرُم من الرّضاع ما يحرُم من النسب،\nزي موقف رسول الله ﷺ دلوقتي، رسول الله ﷺ أخو حمزة من الرضاع وبنت الأخ محرمة على عمها، يبقى هي محرمة على رسول الله ﷺ لأنه عمها من الرضاعة، إن شاء الله تكون النقطة دي واضحة \nخرج رسول الله ﷺ من مكة باتجاه المدينة، \nبعد العمرة دي اتغيرت نظرة ناس كتير من قريش لرسول الله ﷺ وللمسلمين بسبب انبهارهم باللي شافوه من رسول الله ﷺ والمسلمين،\nوكان من الناس المنبهرة دي قائد فرسان مكة \n《خالد بن الوليد》\nبعد ما خرج جيش المسلمين من مكة وقف خالد وسط مجموعة من قريش وقال لهم:\n\"لقد استبان لكلِّ ذي عقلٍ: \nأنَّ محمَّداً ليس بساحرٍ، ولا شاعر وأنَّ كلامه من كلام ربِّ العالمين، فحُقَّ لكلِّ ذي لُبٍّ أن يتَّبعه\"\nيعني بيقول إنه بقى واضح جدا لكل واحد عنده عقل وبيفكر إن محمد ﷺ مش ساحر ولا شاعر وإن الكلام إللي بيقوله هو كلام رب العالمين، \nفبقى واجب على كل ذي عقل أن يتبع محمد ﷺ\nإللي بيقول الكلام ده قائد فرسان قريش إللي هزم المسلمين في أحد، وإللي بقاله عشرين سنة مُعرض عن الإسلام وبيحاربه\nإيه إللي خلاه يغير رأيه كده؟!\nويا ترى كان إيه رد فعل أبي سفيان لما وصل له كلام خالد؟!\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 177, "l": "الجزء 151 | احداث السنه الثامنه من الهجرة | قصة إسلام خالد بن الوليد", "u": "https://www.facebook.com/groups/710210019782034/permalink/836524267150608/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وواحد_وخمسون\n#أحداث_السنة_الثامنة_من_الهجرة\n#قصة_إسلام_خالد_بن_الوليد\nوقفنا المرة إللي فاتت عند خالد بن الوليد لما وقف وسط مجموعة من قريش وقال لهم:\nلقد استبان لكلِّ ذي عقلٍ أنَّ محمَّداً ليس بساحرٍ، ولا شاعر وأنَّ كلامه من كلام ربِّ العالمين، فحقَّ لكلِّ ذي لُبٍّ أن يتَّبعه\"\nيعني بيقول بقى واضح جدا لكل واحد عنده عقل وبيفكر إن محمد ﷺ مش ساحر ولا شاعر وإن الكلام إللي بيقوله هو كلام رب العالمين، \nفبقى واجب على كل ذي عقل أن يتبع محمد ﷺ،\nخالد بن الوليد كان بيقول الكلام ده في وسط مكة وسط المشركين وهو كمان لسه مشرك متخيلين\nإيه بقى إللي خلى خالد بن الوليد يغير رأيه بعد عشرين سنة من الإعراض عن الإسلام ومحاربته مع إنه سمع القرآن قبل كده وسمع أحاديث رسول الله ﷺ\nخالد بن الوليد كان قائد عسكري قوي جدا، وانتم عارفين إن في ناس مش بتعترف إلا بالقوة، \nفهو دلوقتي اتواجه بقوة المسلمين وشاف التغيير الجذري إللي حصل لهم بعد سبع سنين فقط من خروجهم من مكة،\nويمكن ده إللي أخر إسلامه لحد دلوقتي، \nيعني هو له مكانة كبيرة في الجيش المكي ووسط العرب، فهو خاف لو كان دخل في الإسلام؛ المكانة دي تضيع وميبقاش له لازمة على حسب ما كان فاهم،\nميعرفش إن رسول الله ﷺ كان بيحط كل واحد في مكانه المناسب، وإن واحد زيه هيكون له مكانة عظيمة وسط المسلمين وفي قيادة الجيوش،\nيعني موهبته مش هتضيع بالعكس دي هتطور ومكانته هتبقى أفضل \nوهو ده إللي رسول الله ﷺ وصّله لخالد عن طريق أخوه الوليد\nإيه إللي حصل\nأول ما جاء جيش المسلمين مع رسول الله ﷺ ودخلوا مكة لأداء العمرة بالصورة إللي احنا شرحناها المرة إللي قبل إللي فاتت وإزاي كانوا داخلين مظهرين قوتهم،\nخالد بن الوليد مستحملش وترك مكة وخرج،\nفلما دخل جيش المسلمين مكة رسول الله ﷺ سأل أخوه الوليد وكان من الصحابة هو فين خالد، فقال له الوليد يأتي به الله،\nيعني لو كان فيه خير ربنا هيأتي بيه ويدخل في الإسلام،\nفهنا رسول الله ﷺ قال للوليد:\n\"ما مِثل خالد يجهل الإسلام، ولو كان جعل نِكايته وجدّه مع المسلمين على المشركين لكان خيرًا له، ولقدّمناه على غيره\"\nيعني مش واحد زي خالد في عقله يجهل الإسلام،\nولو هو خلى قوته وبأسه وخبرته القتالية مع المسلمين هيبقى أحسن له وهنقدمه على غيره بسبب كفاءته العالية في القتال إللي مفيش في المسلمين زيها\nفالوليد راح يدوّر على خالد عشان يكلمه ويبلغه رسالة رسول الله ﷺ وإللي قاله عنه ملقهوش،\nفكتب له رسالة وأرسلها له مع حد يوصلها له وقال فيها:\nبسم الله الرحمن الرحيم، أما بعد: \n\"فإني لم أرَ أعجبَ من ذهابِ رأيك عن الإسلام، وعَقلُك عَقلُك، ومثلُ الإسلامِ جَهِلَه أحد؟\nوقد سألني رسول الله ﷺ عنك فقال: أين خالد؟ فقلت: يأتي الله به، فقال:\nما مثله جَهِل الإسلام، ولو كان جعل نكايته وجده مع المسلمين على المشركين لكان خيرًا له، ولقدمناه على غيره، فاستدرك يا أخي ما فاتك، فقد فاتتك مواطن صالحة\nيعني الوليد بيقول لخالد أنا مستغرب منك وإنك إزاي لحد دلوقتي مدخلتش الإسلام وانت عقلك حكيم ورأيك سديد، ومفيش حد دلوقتي ميعرفش عن الإسلام،\nفانت إزاي لحد دلوقتي متأخر عن الدخول فيه\nوحتى رسول الله ﷺ سأل عنك وقال إن مش واحد زي خالد يجهل الإسلام ولو دخل الإسلام وجعل قوته مع المسلمين هنحفظ له مكانته وهنقدمه على غيره، فمتضيعش وقت أكثر من كده وأسرع في الدخول للإسلام،\nقبل بقى ما الرسالة توصل لخالد بن الوليد كان هو أصلا وقف وسط مجموعة من قريش وقال لهم الكلمتين إللي قلناهم في الأول:\n\"لقد استبان لكلِّ ذي عقلٍ: أنَّ محمَّداً ليس بساحرٍ، ولا شاعر وأنَّ كلامه من كلام ربِّ العالمين، فحقَّ لكلِّ ذي لُبٍّ أن يتَّبعه\"\nيعني هو كان خلاص الموضوع بقى واضح عنده مفيش مجال للشك إن الإسلام هو الحق،\nوخدوا بالكم إن مش بس موقف المسلمين في العمرة وقوتهم هو إللي أثّر في خالد\nدي في مواقف قبل كده حصلت خلّته يفكر في الإسلام، وينبهر بيه وينبهر برسول الله ﷺ نفسه\nخلوني أقرب لكم الصورة،\nخالد بن الوليد قائد عسكري، وعادة العسكريين إنهم بيدوسوا على كل القيم والأخلاق، والواقع يشهد بكده\nوبيحققوا أهدافهم بغض النظر عن الوسائل إللي بيستعملوها دي شكلها إيه وخالد عارف الكلام ده كويس\nلكن هو بقى شاف في رسول الله ﷺ قائد عسكري مختلف تماما، شاف قائد حكيم قوي يعيش وسط الناس بأخلاق وبمبادئ وقِيَم معينة مش بيخالفها أبدا،\nده غير تفوقه بقى على خالد من الناحية العسكرية\nيعني في غزوة أحد خالد مكنش هيقدر يهجم على المسلمين ويهزمهم لو مكنش الرماة وقعوا في خطأ عصيان أمر رسول الله ﷺ،\nفهو شاف الخطة القتالية إللي رسول الله ﷺ كان حاططها وشاف إنه مكنش قصاده فرصة للفوز لولا خطأ الرماة،\nوطبعا كان موجود في غزوة الأحزاب، وشاف خطة رسول اللهﷺ في الدفاع عن الخندق،\nومننساش موقفه في صلح الحديبية لما كان عايز يهجم على رسول الله ﷺ وجيش المسلمين وهم بيصلوا قبل ما يحصل صلح الحديبية، وبعدين نزلت صلاة الخوف وإن مجموعة تصلي ومجموعة تمسك السلاح؛\nوهو مكنش قال لحد على موضوع الهجوم ده، فرسول الله ﷺ هيعرف إزاي إللي في نفس خالد إلا لو ربنا هو إللي أخبره\nولما شاف إللي حصل قال: \n\"إن القوم ممنوعون\" يعني في حد بيحمي الناس دي،\nفكل الأحداث دي عمالة بتسيب أثر ورا أثر في نفس خالد بن الوليد، \nوشوفوا كده خالد بن الوليد نفسه بيقول إيه، بيقول:\n\"ٌقد شهدتُ هذه المواطن كلها على محمد، فليس موطن أشهدهُ إلا أَنصرفُ وأنا أرى في نفسي أني مُوضِع في غير شيء وأن محمدًا سيظهر\"\nيعني بيقول إنه حضر كل القتال ضد رسول الله ﷺ، وبعد كل قتال ما يخلص بيبقى عنده إحساس إن إللي بيعمله ده ملوش فايدة وإن محمد ﷺ هيظهر على الناس ومحدش هيغلبه\nلحد ما حصل صلح الحديبية والأمور استقرت، هنا بقى خالد قعد يفكر مع نفسه ويقول:\nأي شيء بقي؟ أين المذهب؛ إلى النجاشي؟ فقد اتبع محمدًا، وأصحابه آمنون عنده، فأخرج إلى هرقل؟ فأخرج من ديني إلى نصرانية أو يهودية، فأقيم مع عَجم تابعًا، أو أقيم في داري فيمن بقي؟\nيعني بيقول هو فاضل إيه، هروح فين، أروح للنجاشي؟\nده النجاشي نفسه دخل في الإسلام وأصحاب محمد ﷺ آمنين عنده،\nطيب أروح عند هرقل وأسيب ديني وأدخل في النصرانية أو اليهودية وأعيش مع ناس معرفهمش، \nولّا أفضل في مكة في بيتي مع الناس إللي باقية\nواستمر خالد في الحيرة دي لحد ما جاء رسول الله ﷺ والمسلمين للعمرة، ومبقاش مستحمل بقى وخرج من مكة،\nزي إللي بيكون عايز يهرب من حقيقة قصاده وبيكذب نفسه، وبعدين في الآخر اعترف بالحقيقة دي واستسلم لها\nكلام خالد إللي قاله وسط مجموعة المشركين وصل لسيد مكة أبو سفيان، فأرسل في طلب خالد يسأله عن صحة الكلام ده، إذا كان قاله فعلا ولّا لأ،\nفخالد جاءه وأكد له إنه فعلا قال الكلام إللي وصل له ده، فغضب أبو سفيان لأنه خاف إن الناس تسمع كلام خالد وتدخل في الإسلام، واندفع ناحية خالد في غضب عايز يتقاتل معاه \nفتدخّل بينهم عكرمة بن أبي جهل وكان موجود معاهم وهو من أكثر الناس قُرباً من خالد وبينهم صداقة قديمة، فحجز أبو سفيان عن خالد وقال له:\nمهلاً يا أبا سفيان! فو الله! خِفْتُ لِلَّذي خِفْتَ أن أقول مثل ما قال خالد، وأكون على دينه، أنتم تقتلون خالداً على رأيٍ رآه، وهذه قريش كلُّها تبايعت عليه،\nوالله! لقد خِفتُ ألاّ يحول الحول حتَّى يتَّبعه أهل مكَّة كلُّهم\"\nيعني بيقول لأبي سفيان استنى بس اهدى، أنا كمان خفت إني أقول للناس زي ما قال خالد ، وأنا نفسي خفت لأكون على دين محمد بعد إللي شوفته من محمد وأصحابه\nثم انت عايز تقاتل خالد عشان قال رأيه بسبب انبهاره بمحمد وأصحابه وقريش أصلا كلها منبهرة بيه،\nده أنا خايف متعديش السنة إلا وكل أهل مكة داخلين الإسلام\nتخيلوا بقى لما ده كان حال قادة مكة أمّال بقى بعامة الناس كان انبهارهم عامل إزاي بالمسلمين إللي كانوا من سبع سنين بس بيُعذبوا وبيُطاردوا\nوصلت رسالة الوليد لخالد، فقرأها خالد وقرأ الكلام إللي رسول الله ﷺ قاله، فكانت الرسالة دي هي الضربة القاضية زي ما بيقولوا\nتشجع خالد بن الوليد وأخذ القرار بإنه يذهب للمدينة ويسلم عند رسول الله ﷺ ويكون مع المسلمين،\nوشاف خالد رؤيا إنه كان في بلد ضيقة جَدْباء مفيهاش زرع، وبعدين خرج إلى بلد أخضر واسع، فقال إنه لما يروح المدينة هيسأل أبو بكر عن تفسير الرؤيا دي،\nخالد بن الوليد أخذ القرار إنه يهاجر للمدينة، فقال في نفسه:\nمن أُصاحب إلى رسول الله\nيعني أدعو مين للإسلام وأخذه معايا لرسول الله ﷺ، فوهو بيفكر قابل صفوان بن أمية، فقال خالد لصفوان:\n\"يَا أَبَا وَهْبٍ!\nأَمَا تَرَى مَا نَحْنُ فِيهِ، إِنَّمَا نَحْنُ أَكَلَةُ رَأْسٍ، وَقَدْ ظَهَرَ مُحَمَّدٌ عَلَى الْعَرَبِ وَالْعَجَمِ، فَلَوْ قَدِمْنَا عَلَى مُحَمَّدٍ وَاتَّبَعْنَاهُ، فَإِنَّ شَرَفَ مُحَمَّدٍ لَنَا شَرَفٌ\"\nيعني بيقول لصفوان انت مش شايف الحال إللي وصلنا له، وإزاي بقينا شوية صغيرين بعد ما محمد ﷺ ظهر على العرب وعلى العجم، فلو احنا دلوقتي روحنا لمحمد ودخلنا معاه في الإسلام فشرفه من شرفنا لأنه مننا وهنبقى معاه،\nلكن صفوان رفض جدا الفكرة، وقال لخالد:\n\"لَوْ لَمْ يَبْقَ غَيْرِي مَا اتَّبَعْتُهُ أَبَدًا\"\nيعني لو كل الناس اتبعوه ومتبقاش غيري مش هتبعه\nوبعدين كل واحد مشي في طريقه، فخالد قال في نفسه:\nهَذَا رَجُلٌ قُتِلَ أَخُوهُ وَأَبُوهُ بِبَدْرٍ، يعني له حق يرفض الإسلام بسبب إن في ثأر بينه وبين المسلمين،\nفبعدها قابل عكرمة بن أبي جهل،\nفقال له زي ما قال لصفوان، فكان رد عكرمة نفس رد صفوان بن أمية، إنه لو الناس كلها اتبعت محمد ﷺ وهو الوحيد إللي باقي مش هيتبعه،\nفقال له خالد: فَاكْتُمْ عَلَيَّ، يعني خلي الكلام ده بيني وبينكم ومتقلوش لحد، فقال له عكرمة إنه مش هيقول لحد،\nراح خالد لبيته وجهّز راحلته، يعني الجمل إللي هيسافر عليه وخرج، وهو ماشي قابل واحد من المشركين اسمه عثمان بن طلحة، فقال خالد في نفسه:\nده صاحب ليّ، فلو قلت له إللي أنا ناوي عليه، يمكن ييجي معايا، عثمان بن طلحة ده من بني عبد الدار، \nولو تفتكروا في غزوة أحد إللي كان المسؤول عن حماية راية المشركين هم بني عبد الدار وقلنا إن قُتل منهم ستة، كل ما كان واحد فيهم يمسك الراية يُقتل،\nأهه الستة إللي اتقتلوا دول هم: أبو عثمان بن طلحة وعمه وإخواته الأربعة \nفخالد كان ناوي يكلمه، وبعدين افتكر أهله إللي اتقتلوا في أُحد، وهو كان لسه مكلم صفوان ورفض بشدة لأن أبوه وأخوه قُتلوا في بدر، وكلم عكرمة ورفض بشدة لأن أبوه قُتل في بدر، فده بقى اتقتل له ستة فمن باب أولى إنه يرفض عَرْض خالد ومش بعيد يقوم عليه يقتله\nإللي هو إزاي يعني، واحد قَتل ستة من أهلي وعايزني أروح أتبعه\nفده إللي كان بيفكر فيه خالد، ومكنش ناوي يكلمه عشان ميفكروش بأهله إللي اتقتلوا وميقلبش عليه المواجع زي ما بنقول، وبعدين قال: طب أنا كده كده ماشي ومش هقعد في مكة خليني أقول له وخلاص ومش هقابله تاني،\nفبدأ خالد يكلمه وقال له نفس الكلام إللي قاله لعكرمة وصفوان وقال له : \"إِنَّمَا نَحْنُ بِمَنْزِلَةِ ثَعْلَبٍ فِي جُحْرٍ، لَوْ صُبَّ فِيهِ ذَنُوبٌ مِنْ مَاءٍ لَخَرَجَ\"\nيعني احنا عاملين زي الثعلب إللي مستخبي في جحر لو اتصب عليه شوية مية هيخرج، يقصد يعني إن مبقاش في مفر من الدخول في الإسلام،\nفسبحان الله الرجل إللي قُتل له ستة من أهله وافق على كلام خالد وصفوان وعكرمة موافقوش مع إن عدد قتلاهم أقل،\nومش بس كده ده قال له أنا أصلا خارج النهاردة من بيتي وأنا ناوي إني أروح المدينة لرسول الله ﷺ\n☆وهنا نتعلم نقطة مهمة جدا\nوهي: إن مش دايما الحاجة إللي ظاهرها مستحيل وصعبة لازم هتكون فعلا مستحيلة زي ما احنا متصورين،\nمش معنى إننا حاولنا في حاجات سهلة وفشلنا ومقدرناش نحققها يبقى كل المحاولات التانية الأصعب هتفشل، \nخالد بن الوليد كان صرف نظر إنه يكلم عثمان بن طلحة لحد آخر لحظة، وهو مكنش عارف إن ربنا بيجهزه له عشان يصاحبه في السفر،\nهو كمل المحاولة لأنه كده كده مش خسران حاجة، وسايب مكة وماشي،\nوهو حاول مرتين وملقاش استجابة ومع ذلك عمل محاولة أخيرة مع عثمان، وكانت النتيجة إنه نجح،\nفالإنسان طول ماهو بيحاول هينجح في يوم من الأيام، إللي بيصبر ويستمر في المحاولة هو بس إللي ربنا هيّسر له النجاح\nمثلا يعني: \nساعات بننصح حد وميستجبش للنصيحة فننصح غيره وميستجبش وغيره وغيره فيدخل الإحباط في قلوبنا ونقول مفيش فايدة،\nفنيجي في موقف يبقى محتاجين ننصح حد، فالشيطان يقول لنا مفيش فايدة ماحنا جربنا قبل كده ومكنش في نتيجة، هي بقى المرة دي يعني هي إللي هتنفع\nمع إننا مش خسرانين حاجة أصلا بالعكس، أي نصيحة بنقولها للناس هي في ميزان حسناتنا سواء الناس استجابت أو لأ\nاحنا علينا المحاولة وبس وملناش دعوة بالنتيجة،\nزي ما خالد بن الوليد عمل مع عثمان بن طلحة، حاول آخر محاولة قبل ما يمشي ويسيب مكة وكانت المفاجأة إن عثمان بن طلحة إللي كان أكثر الثلاثة ألما ومُصاباً ويستحيل إنه يوافق هو إللي استجاب لدعوة خالد بن الوليد وكمان كان مجهز نفسه للخروج، يعني شوفوا التوفيق بتاع ربنا \nهو حاول وميأسش وفي الآخر ربنه وفقه\nالمهم بقى، هم الاتنين اتفقوا إنهم يتقابلوا في مكان معين اسمه يأْجَجَ، وقالوا لبعض إللي يوصل الأول يستنى التاني،\nفخرج كل واحد منهم في وقت السَّحر لوحده وقبل ما يطلع الفجر كانوا متقابلين في يأْجَجَ واتجهوا ناحية المدينة،\nلما وصلوا لمنطقة الْهَدَة لقوا فيها مين\nلقوا فيها عمرو بن العاص \nفقال لهم عمرو: مَرْحَبًا بِالْقَوْمِ\nفقالوا له: وَبِكَ\nفسألهم:\nإِلَى أَيْنَ مَسِيرُكُمْ؟ يعني انتم مسافرين فين، فردوا عليه بسؤال : وَمَا أَخْرَجَكَ؟ \nيعني انت إيه إللي جابك هنا، فقال لهم عمرو: وَمَا أَخْرَجَكُمْ؟\nيعني وانتم كمان إيه إللي جابكم هنا،\nفلقوا إن الموضوع كده مش نافع\nكل واحد بيرد على التاني بسؤال انت إيه إللي جابك وانتم إيه إللي جابكم،\nفواضح إن كل طرف فيهم عايز يخبي سبب خروجه،\nطبعا لا عمرو عارف الحوار إللي حصل مع خالد وعثمان بن طلحة، ولا عثمان وخالد عارفين إن عمرو كان عند النجاشي وأسلم ومخبي إسلامه\nفهنا عثمان وخالد قالوا لعمرو إنهم جايين عشان يدخلوا في الإسلام ويتبعوا رسول الله ﷺ،\nفقال لهم عمرو :\nوَذَاكَ الَّذِي أَقْدَمَنِي\nيعني هو ده إللي أنا جاي عشانه أنا كمان، فانطلق الثلاثة ناحية المدينة لحد ما دخلوا المدينة وأَنَاخُوا الجمال بتاعتهم في منطقة الحرّة،\n يعني قعدوها في الأرض ونزلوا من عليها،\nوغيّر خالد هدومه ولبس ملابس أفضل، واتجه ناحية رسول الله ﷺ،\nفي الوقت ده كان الخبر وصل لرسول الله ﷺ إن خالد وعمرو وعثمان جايين لرسول الله ﷺ، أنا شخصيا مش قادر أتصور فرحة رسول الله ﷺ بإسلام الثلاثة دول\nفوهم متجهين لرسول الله ﷺ قابلهم الوليد أخو خالد وقال لهم:\n\"إِنَّ رَسُولَ اللَّهِ ﷺ قَدْ أُخْبِرَ بِكَ، فَسُرَّ بِقُدُومِكَ، وَهُوَ يَنْتَظِرُكُمْ\"\nيعني رسول الله ﷺ عرف إنكم جيتكم وفرح بقدومكم وهو مستنيكم،\nفأسرع الثلاثة في المشي لحد ما قرّبوا من رسول الله ﷺ ونظر خالد لرسول الله ﷺ فلقاه بيتبسم له،\nويُقال إن رسول الله ﷺ لما رآهم وهم جايين قال لأصحابه:\n \"لقد رَمَتْكم مكة بفَلَذات أكبادها\"\nأنا بحثت عن صحة الحديث ده ملقتش حد بينكر إن رسول الله ﷺ قال الكلام أو بيأكد إنه قاله، \nهي رواية موجودة فقلته على سبيل الخبر وأنه مش هيأثر في حلال أو حرام مثلا أو حاجة في العقيدة\nوالكلمة إللي قالها رسول الله ﷺ دي معناها:\nإن مكة أعطتكم أشراف قريش وقادتها الخُلّص، هو فاضل مين بعد أرطبون العرب عمرو وقائد فرسان قريش وابن ريحانة العرب خالد، وعثمان بن طلحة إللي معاه مفتاح الكعبة\nالمهم إن رسول الله ﷺ فضِل يتبسم لحد ما وصل خالد عنده ﷺ، فسلم عليه بالنبوة وقال :\nالسلام عليك يا رسول \nفرد رسول الله ﷺ عليه السلام بِوَجْهٍ طَلْقٍ، بشوش ضاحك\nفقال خالد بن الوليد لرسول الله ﷺ:\n\" إِنِّي أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّكَ رَسُولُ اللَّهِ\"\nفقال له رسول الله ﷺ:\" تَعال\" قرب يعني، وبعدين رسول الله ﷺ قال له:\n\"الْحَمْدُ لِلَّهِ الَّذِي هَدَاكَ، قَدْ كُنْتُ أَرَى لَكَ عَقْلًا رَجَوْتُ أَنْ لَا يُسْلِمَكَ إِلَّا إِلَى خَيْرٍ\"\nيعني رسول الله ﷺ بيقوله إن كان شايف في خالد رجاحة العقل وسداد في الرأي وكان يرجو إن عقله يقوده للإسلام،\nفقال له خالد:\n\"يَا رَسُولَ اللَّهِ!\n قَدْ رَأَيْتَ مَا كُنْتُ أَشْهَدُ مِنْ تِلْكَ الْمَوَاطِنِ عَلَيْكَ مُعَانِدًا لِلْحَقِّ، فَادْعُ اللَّهَ أَنْ يَغْفِرَهَا لِي \"\nيعني انت يا رسول الله شوفت إللي أنا كنت بعمله من عنادي وقتالي لك وللمسلمين، فادع الله إنه يغفر لي كل الغلط إللي عملته، فقال له رسول الله ﷺ:\n\" الْإِسْلَامُ يَجُبُّ مَا كَانَ قَبْلَهُ\" يعني الإسلام بيمسح أي حاجة قبله،\nفقال خالد:  يَا رَسُولَ اللَّهِ، عَلَى ذَلِكَ\nيعني كأنه بيقوله ريّحني وادعي لي بس إن ربنا يغفر لي إللي فات، فقال رسول الله ﷺ \n\"اللَّهُمَّ اغْفِرْ لِخَالِدِ بْنِ الْوَلِيدِ كُلَّ مَا أَوْضَعَ فِيهِ مِنْ صَدٍّ عَنْ سَبِيلِكَ\"\nوبايع خالد بن الوليد رضي الله عنه رسول الله ﷺ على الإسلام\nولما قابل خالد أبو بكر الصديق رضي الله عنه سأله عن الرؤيا إللي شافها إنه كان في أرض ضيقة وبعدين خرج إلى أرض واسعة، فقال له أبو بكر:\n\"هو مَخْرجك الذي هداك الله للإسلام، والضيق الذي كنت فيه من الشرك\"\nيعني الأرض الضيقة إللي مكنش فيها زرع دي كانت الشرك، والأرض الخضراء الواسعة هي الإسلام إللي دخلت فيه.\nجه بقى الدور على عمرو بن العاص في مبايعة رسول الله ﷺ، إيه الحوار إللي حصل بين رسول الله ﷺ وعمرو بن العاص، ده إللي هنعرفه الجزء الجاي إن شاء الله \n☆ملحوظة:\nالقصة دي كلها محصلتش في يوم ولّا اتنين\nده الحوارات دي قعدت من شهر ذي القعدة من السنة السابعة للهجرة بعد ما رسول الله ﷺ خلص العمرة لحد ما راحوا لرسول الله ﷺ في المدينة في شهر صفر من السنة الثامنة للهجرة وأسلموا، يعني ثلاثة أشهر\nطبعا كان في أحداث بتحصل مع رسول الله ﷺ خلال الثلاثة أشهر دول هنعرفها إن شاء الله لما نخلص حوار عمرو بن العاص مع رسول الله ﷺ"}, {"n": 178, "l": "الجزء 152 | احداث السنه الثامنه من الهجرة | السرايا بعد عمرة القضاء", "u": "https://www.facebook.com/groups/710210019782034/permalink/836524433817258/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_واثنان_وخمسون\n#أحداث_السنة_الثامنة_من_الهجرة\n#السرايا_بعد_عمرة_القضاء\nاتكلمنا المرة إللي فاتت عن قصة إسلام خالد بن الوليد رضي الله عنه وإنه توجه لرسول الله ﷺ في المدينة ومعاه عثمان بن طلحة وفي الطريق قابلوا عمرو بن العاص إللي كان متجه للمدينة هو كمان وراحوا للمدينة مع بعض،\nلو تفتكروا كنا اتكلمنا عن قصة إسلام عمرو بن العاص على يد النجاشي في الجزء المائة واثنان وثلاثون،\nوقلنا إن عمرو قعد عند النجاشي فترة بعد ما أسلم وبعدين توجه للمدينة، \nأهه في طريقه للمدينة قابل خالد وعثمان وكلهم دخلوا المدينة مع بعض وراحوا لرسول الله ﷺ وفرح رسول الله ﷺ بإسلامهم،\nبايع خالد بن الوليد رسول الله ﷺ على الإسلام وعرفنا قصة بيعته، جه الدور بقى على بيعة عمرو بن العاص،\nقال عمرو لرسول الله ﷺ:\n\"ابسط يمينك فأُبايعك\"\nيعني مد إيدك يا رسول الله عشان أبايعك على الإسلام، \nفبسط رسول الله ﷺ يمينه، فقبض عمرو يده \nفرسول الله ﷺ سأله:\nما لك يا عمرو؟! يعني قبضت إيدك ليه، فقال عمرو لرسول الله ﷺ: أردت أن أشترط\nيعني أنا هسلم بس بشرط، فسأله رسول الله ﷺ عن الشرط بتاعه، فقال له عمرو: أن يُغفر لي!\nفقال له رسول الله ﷺ:\nأَمَا علمت أن الإسلام يهدم ما كان قبله، وأن الهجرة تهدم ما كان قبلها، وأن الحج يهدم ما كان قبله؟\nيعني بيقول له إن الإسلام بيمسح إللي قبله من الذنوب والمعاصي وكذلك الهجرة والحج بيمسحوا إللي قبلهم من الذنوب المعاصي، فمد عمرو يده وبايع رسول الله ﷺ على الإسلام،\nإسلام عمرو وخالد يعتبر نقطة تحول مش بس في تاريخ مكة ولا تاريخ المدينة ولا حتى في تاريخ في شبه الجزيرة العربية، ده نقطة تحول في تايخ العالم كله، \nتخيلوا إنه تم فتح بلاد الشام وبلاد فارس وبلاد ما وراء النهر، وفُتحت أرمينية وبلاد كثيرة جدا على يد خالد بن الوليد بعدين، وعمرو بن العاص فتح مصر وفلسطين وغيرها من البلاد، \nشوفوا بقى كم من المسلمين وكم من الأعمال الصالحة وكم من العلم انتشر في الأرض وكل ده في ميزان حسنات البطلين عمرو وخالد،\nإن شاء الله لو ربنا أَذِن وكان في العمر بقية هنتكلم عن فتوحاتهم بتفصيل أكبر في سلسلة الخلفاء الراشيدين\nتقدم  عثمان بن طلحة بعد عمرو وبايع رسول الله ﷺ على الإسلام،\nعمرو بن العاص لما أسلم كان عمره حوالي اثنان وخمسون سنة، وخالد كان عمره حوالي سبعة وثلاثين سنة، أما عثمان بن طلحة فمفيش خبر عن عمره كان أد إيه لما أسلم،\nإسلام عمرو وخالد وعثمان كان في شهر صفر من السنة الثامنة للهجرة.\nهنرجع بقى بالزمن للأحداث إللي حصلت مع رسول الله ﷺ بعد عمرة القضاء في السنة السابعة للهجرة،\nبعد ما رجع رسول الله ﷺ للمدينة بعد عمرة القضاء جهّز سرية في شهر ذي الحجة بقيادة ابن أبي العَوجاء السُّلَمي  لبني سُلَيم إللي كانوا يسكنوا صحراء نجد على طريق القوافل بين المدينة ومكة،\nوبني سليم دول من قبائل غطفان، ولو تفتكروا بني سليم كانوا دايما يعملوا مشاكل مع المسلمين من بعد غزوة بدر، حتى إن رسول الله ﷺ خرج لهم في غزوة واتكلمنا عنها في الجزء الخامس والستين،\nفأخرج لهم رسول الله ﷺ المرة دي سرية مكونة من خمسين فارس بقيادة ابن أبي العوجاء السُّلَمي زي ما قلنا،\nبني سليم كان لهم عَين، جاسوس يعني بيراقب الأحوال من خارج القبيلة، فلما شاف الخمسين فارس جايين ناحية قبيلته رجع بسرعة لبني سليم وأخبرهم بالخبر،\nتجهز بنو سُليم وأعدوا عدتهم للقتال وجمعوا مقاتلين كتير، فلما وصلت لهم سرية رسول الله ﷺ دعوهم للإسلام فبني سُليم قعدوا يرموهم بالسهام وقالوا لهم:\nلا حاجة لنا إلى ما دعوتم إليه\nيعني مش عايزين حاجة من الإسلام بتاعكم ده، وفعلا مسمعوش منهم واستمروا يرموهم بالسهام وكل شوية ييجي مدد لبني سُليم لحد ما حاوطوا المسلمين من كل مكان، \nوقاتل المسلمون قتال شديد لحد ما قُتل معظمهم وأُصيب ابن أبي العوجاء السُّلَمي بجراح كثيرة؛ فتحامل على نفسه ورجع للمدينة مع إللي اتبقى من أصحابه، وكان رجوعهم في شهر صفر من العام الثامن للهجرة\nفي شهر صفر برده أخرج رسول الله ﷺ سرية بقيادة غالب بن عبد الله الليثي إللي خرج قبل كده في أكثر من سرية في العام السابع الهجري لقبائل غطفان واتكلمنا عنها برده،\nرسول الله ﷺ أخرجه المرة دي كمان في سرية مكونة من حوالي مائة وثلاثين رجل لبني المُلَوّح وهم فرع من بني لَيْث،\nوالسبب في السرية دي هو تأديب أعراب قبيلة بني المُلَوّح إللي ساعدوا المشركين على المسلمين قبل كده، \nوكمان عشان رسول الله ﷺ يعرف أخبارهم ويمنعهم من عمل أي تحالفات ضد دولة الإسلام\nخرجت السرية من المدينة في اتجاه بني المُلَوّح، في الطريق  قابلوا رجل اسمه الحارث بن مالك الليثي وكان لقبه\n \"ابن البَرصاء\" وكان عدو شديد للمسلمين، فأسروه وربطوه، فقال لهم إنه جاء عشان يعلن إسلامه، فقالوا له لو انت فعلا جاي مسلم فمش هيضرك رباط يوم وليلة،\nولو انت بتدعي الإسلام وانت جاسوس للمشركين هنعرف ده،\nفغالب بن عبد الله الليثي خلى رجل أسود كان معاهم يقعد يحرس الحارث بن مالك، وقال له اقعد احرسه لحد ما نرجع لك تاني ولو الحارث عمل معاك مشاكل اقتله،\nكملت السرية طريقها لحد ما وصلت منطقة الكَديد إللي فيها بني المُلَوّح،\nوصلت السرية عند غروب الشمس، فأرسلوا واحد منهم يستطلع الأخبار، فطلع على تل ونام على الأرض وقعد يراقب الناس إللي كانوا موجودين في المنطقة وبيسقوا الأنعام بتاعتهم من وراء التل،\nواحد منهم شاف سواد على التل، فقال لزوجته:\nأنا شايف سواد على التل مكنش موجود الصبح، فشوفي كده لتكون الكلاب جرّت بعض الأوعية بتاعتك\nفزوجته قالت له كل حاجة موجودة مفيش حاجة ضايعة، فقال لها طيب هاتيلي قوسي وسهمين كده، وأخذ السهم ورماه ناحية الصحابي فجه السهم في جنبه\nفالصحابي نزع السهم ورماه ومتحركش من مكانه، فالرجل راح واخد السهم التاني ورماه فأصاب كتف الصحابي،\nفالصحابي نزع السهم من كتفه ومتحركش من مكانه، \nفقال الرجل لزوجته: \n\"ِوالله لقد خالَطه سَهْمَاي ولو كان دابة لتحرك فإذا أصبحت فابتغي سهمي فخذيهما لا تمضغهما علي الكلاب\"\nيعني انا متأكد إن السهمين بتوعي أصابوا السواد ده، ولو السواد ده كان حاجة حية كان اتحرك، \nفلما ييجي الصبح ابقي روحي هاتيلي السهمين بتوعي عشان الكلاب متمضغهمش،\nالسرية استنت لحد ما المجموعة دي احتلبوا وأكلوا وهدأت عندهم الحركة وعدى جزء من الليل وبعدين هجموا عليهم وقتلوا منهم مَن قتلوا وساقوا الأنعام معاهم ورجعوا لطريقهم ناحية المدينة،\nوخرج واحد منهم يصرخ وتوجه إلى قومهم بيطلب منهم المساعدة ويقول لهم إن المسلمين أغاروا عليهم،\nفالسرية أسرعت واتجهت ناحية الحارث إللي كان مربوط والرجل إللي كان بيحرسه وأخذوهم ومشيوا،\nفالناس اتجمعوا ولحقوا بسرية المسلمين وكانوا أعداد كبيرة جدا، ومكنش بينهم غير بطن الوادي يفرق بينهم، \nيعني المسلمين كانوا على ناحية والمشركين على الناحية التانية ويادوب المشركين يعدوا بس الوادي ويلحقوا بالمسلمين\nوفجأة لقوا سيل جاي في الوادي حَالَ بين الفريقين،\nومكنوش عارفين السيل ده جه منين ومكنش في مطر خالص الفترة دي عشان الوادي يفيض كده بالماء، ومحدش فيهم قِدر إنه يعدي الناحية التانية من شدة السيل\nوفضلوا واقفين يبصوا على المسلمين وهم بيسوقوا الأنعام بتاعتهم ومحدش فيهم قادر يعمل حاجة، وظهرت لهم قوة المسلمين\nرجع المسلمون للمدينة بالغنائم، وأسلم فعلا الحارث بن مالك رضي الله عنه\nمع مجيء غالب بن عبد الله الليثي كان رسول الله ﷺ مجهز سرية تانية مكونة من مائتين رجل من الصحابة بقيادة الزبير  بن العوام رضي الله عنه عشان يروح يقاتل بني مُرة ناحية فدك إللي قتلوا أصحاب بشير بن سعد لو تفتكروا،\nوكان بشير بن سعد أُصيب بجراح وراح عند واحد من اليهود في فدك واليهودي عالج جروحه وبعدين رجع لرسول الله ﷺ في المدينة وأخبره باللي حصل معاه،\nعامة تفاصيل سرية بشير بن سعد هتلاقوها في الجزء مائة وأربعة وأربعين\nفرسول الله ﷺ كان عايز يقتص للصحابة إللي اتقتلوا دول، فجهز السرية دي بقيادة الزبير بن العوام،\nفجاء غالب بن عبد الله الليثي منتصرا فقال رسول الله ﷺ للزبير اقعد، وولّى غالب بن عبد الله الليثي إللي كان لسه جاي من الكديد قيادة السرية دي لمنطقة فدك إللي قُتل فيها أصحاب بشير بن سعد\nراح غالب بن عبد الله الليثي مع المائتين رجل للمنطقة إللي قُتل فيها أصحاب بشير بن سعد وقاتل المشركين هناك وانتصر عليهم وأخذ منهم غنائم،\nفي شهر ربيع الأول جهز رسول الله ﷺ سرية بقيادة \n شجاع بن وهب الأَسدي مع أربعة وعشرين رجل لجَمْع من هوازن، \nوكانوا بيمشوا بالليل ويناموا بالنهار عشان محدش يحس بيهم، لحد ما وصلوا للمكان المطلوب وهجموا على المشركين وانتصروا عليهم وأخذوا منهم غنائم، ورجعت السرية بعد خمسة عشرة يوما.\nزي ماحنا شايفين الدولة الإسلامية من بعد صلح الحديبية وهي من ارتفاع لارتفاع ومن مجد لمجد، وانتصارات ورا بعضها،\nوالناس في الجزيرة العربية شايفين نمو الدولة الإسلامية وقوتها إللي بتزيد يوم عن يوم،\nوطبعا في بعض القبائل شافت إن الدولة الإسلامية دي خطر عليهم مع إن مكنش في بينهم وبين المسلمين أي علاقات مباشرة، والقبائل دي كانت موجودة في شمال شبه الجزيرة العربية، \nفبدأوا يتحرشوا بالدولة الإسلامية ووصل الموضوع لإنهم يقتلوا المسلمين بدون أي ذنب\nولو تفتكروا قبيلة جُذام كانت من قبائل شمال شبه الجزيرة العربية وكانت اعتدت على الصحابي دِحية الكلبي وهو راجع من عند هرقل وأخذوه منه الهدايا إللي كانت معاه كده بلطجة عشان بس هو مسلم\nوبعدين رسول الله ﷺ أرسل لهم سرية بقيادة زيد بن حارثة وقتل زيد زعيمهم وابنه، ممكن ترجعوا لتفاصيل السيرة دي في الجزء مائة واثنين،\nوقبائل شمال شبه الجزيرة العربية بصفة عامة كانوا قبائل قوية ومن أشهر القبائل دي قبيلة جُذام زي ما قلنا وقبيلة لَخْم، وغسّان، وقُضَاعة وغيرها،\nومعظم القبائل دي كانت على دين النصرانية لأنهم كانوا قريبين من بلاد الشام،\nوبلاد الشام كانت مُحتلة من الدولة الرومانية، إللي كانت فارضة سيادتها على المنطقة دي كلها، وكانت القبائل دي مُوالية للدولية الرومانية،\nيعني زعماء القبائل دي على الرغم من مكانتهم إلا إنهم كانوا عبارة عن مجرد عمال لـهرقل على بلادهم،\nكعادة يعني الدولة الصغيرة في التعامل مع الدولة العالمية العملاقة،\nوالقبائل دي بسبب علاقتهم مع الدولة الرومانية تقدروا تقولوا كده إنهم كانوا شايفين نفسهم شوية\nيعني إللي بيدعمهم هرقل أعظم ملك في الأرض ساعتها بعد ما هزم جيش فارس، فمين بقى إللي يقدر يقف قصادهم ولّا يحاسبهم على أي حاجة يعملوها\nفكان أول مشكلة عملوها مع المسلمين هي هجومهم على دحية الكلبي زي ما قلنا،\nولو تفتكروا برده الحارث بن أبي شَمِر أو شُمّر الغَسّاني أمير دمشق إللي رسول الله ﷺ أرسل له رسالة يدعوه للإسلام \nفلما وصلته الرسالة كان رد فعله زي رد فعل كسرى ورمى رسالة رسول الله ﷺ وقال بكل كبر هو مين ده إللي يقدر ياخد مني ملكي،\nوجهز جيش للهجوم على المدينة لكن هرقل منعه من كده زي ما حكينا في الجزء المائة واثنين وثلاثين\nحصلت بقى حادثة جديدة بين المسلمين وبين قبيلة قُضَاعة إللي هي برده من قبائل شمال شبة الجزيرة العربية،\nرسول الله ﷺ أرسل سرية من خمسة عشرة رجلا بقيادة كعب بن عُمير الغِفاري لمنطقة ذات أطلاح وراء وادي القرى من أرض الشام،\nفلقوا مجموعة من بني قُضاعة، فدعوهم إلى الإسلام فلم يستجيبوا لهم، وقعدوا يرموهم بالسهام،\nفلما لقى الصحابة الوضع كده بدأوا يقاتلوا ويدافعوا عن نفسهم، واشتد القتال بينهم لحد ما قُتلوا جميعا رضي الله عنهم، ما عدا واحد بس كان جريح والمشركين فكروه مات وتركوهم ومشيوا،\nفلما جاء الليل، الجريح ده تحامل على نفسه لحد ما رجع للمدينة لرسول الله ﷺ وأخبره باللي حصل،\nالخبر كان شديد على رسول الله ﷺ، فالحادثة دي زي حادثة ماء الرجيع إللي قُتل فيها الصحابة غدرا،\nهم مخرجوش لقتال لكنهم خرجوا للدعوة وأعلنوا كده للمجموعة دي ومع ذلك قتلوهم،\nفقرر رسول الله ﷺ إنه يجهز سرية ويُرسلها لتقتص للصحابة إللي اتقتلوا دول، \nلكن وصلت الأخبار لرسول الله ﷺ إن المجموعة دي تركت المكان ده ومشيت لمكان تاني،\nوانتم عارفين إن القبائل العربية قديما مكنتش مستقرة في مكان واحد وبتنتقل من مكان لمكان بحسب العشب والماء،\nفدي كده تالت حادثة تحصل مع قبائل شمال شبة الجزيرة العربية، \nوالحوادث دي كده تُنبيء إن في صدام هيحصل بين المسلمين وبين المنطقة الشمالية دي\nوجت بقى القشة التي قصمت ظهر البعير\nرسول الله ﷺ أرسل رسالة إلى عظيم بُصرى بالأردن يدعوه فيها إلى الإسلام، وكان حامل الرسالة الصحابي الحارث بن عمير رضي الله عنه، \nوهو في الطريق اعترض طريقه شُرَحْبِيل بن عمرو الغَسّاني، وهو عامل هرقل على منطقة البَلقاء في الأردن، وعرف إن ده رسول رسول الله ﷺ فأخذه شُرَحْبِيل وقيده وقتله رضي الله عنه \nقتل الرسل جريمة بشعة؛ لأن الأعراف تقضي بعدم قتل الرسل مهما كان لأنهم مجرد حاملي للرسائل، فشُرَحْبِيل بن عمرو الغَسّاني ده كده تعدى حدوده،\nوياريت الموضوع وقف على كده، ده الدولة الرومانية ونصارى الشام بدأوا يتعقبوا كل مَن أسلم ويقتلوه لدرجة إنهم قتلوا والي مَعان في الأردن؛ لأنه كان أسلم\nيعني قمة البلطجة، ما هم شايفين نفسهم بقى ومحدش مالي عينهم ومفكرين إن محدش هيقدر عليهم ويوقفهم عند حدّهم\nوهي دي عادة الطغاة وأعوانهم، لما يشموا نفسهم ويبقى معاهم قوة يطيحوا في خلق الله ولا يهمهم أعراف ولا أخلاق ولا دين ولا أي حاجة، \nربنا ياخدهم ويريحنا منهم كلهم\nوصلت الأخبار لرسول الله ﷺ، وطبعا كان لازم رسول الله ﷺ ياخد موقف عشان يدافع عن هيبة الدولة الإسلامية ويثأر لكرامتها، وعشان يُأَمّن حركة الدعاة المسلمين للمناطق الشمالية من الجزيرة العربية،\nوكمان عشان يُأَمّن خط سير التجار المسلمين من وإلى الشام\nدلوقتي بقى قصاد رسول الله ﷺ مشكلتين في الشمال مطلوب منه ياخد فيهم موقف\n◇المشكلة الأولى:\nمشكلة الدولة الرومانية، والقبائل العربية المتحالفة معاها إللي معظمها قبائل نصرانية زي لخم، وجُذام، وغسّان، وغيرها من القبائل زي ما قلنا من شوية.\n◇المشكلة الثانية:\nمشكلة قبائل قُضاعة إللي اعتدوا على خمسة عشر صحابياً رضي الله عنهم وأرضاهم وقتلوهم، والقبائل دي قبائل كبيرة هي كمان لكنها منفصلة عن القبائل التانية المتحالفة مع الدولة الرومانية.\nيا ترى رسول الله ﷺ هيبدأ بأنهي مشكلة وهيتصرف إزاي في الموقف ده؟!\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 179, "l": "الجزء 153 | احداث السنه الثامنه من الهجرة | التجهيز لمعركة مؤته", "u": "https://www.facebook.com/groups/710210019782034/permalink/836540223815679/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاثة_وخمسون\n#أحداث_السنة_الثامنة_من_الهجرة\n#التجهيز_لمعركة_مؤتة\nاتكلمنا المرة إللي فاتت عن الأحداث إللي حصلت بين المسلمين وبين قبائل شمال شبه الجزيرة العربية،\nوقلنا إن رسول الله ﷺ بيواجه مشكلتين لازم ياخد منهم موقف حاسم،\nالأولى: هي مشكلة قبيلة قُضاعة إللي قتلت أربعة عشرة رجل من المسلمين، \nوالثانية: مشكلة القبائل النصرانية المتحالفة مع الدولة الرومانية،\nرسول الله ﷺ شاف إنه يعالج واحدة ورا التانية وميواجهش الاتنين مع بعض، \nلأن مش صح إن رسول الله ﷺ يفتح على نفسه جبهتين للقتال مع قبائل قوية كده وكمان القبائل التانية مسنودة من الدولة الرومانية،\nوخصوصا إن دولة الإسلام أه بقت قوية دلوقتي، لكن لسه في البداية برده، مينفعش نفتح جبهات كتير للقتال\nفاختار رسول الله ﷺ إنه الأول يواجه مشكلة القبائل العربية المُتنصّرة المتحالفة مع الدولة الرومانية في الشَّمال،\nلأن المناطق دي خطيرة جدا وأعداد القبائل هناك كبيرة ومن المُتوقع إن الدولة الرومانية ممكن تساعد القبائل دي،\nورسول الله ﷺ كان من عادته إن هو إللي يبدأ بالهجوم عشان عنصر المفاجأة له عامل كبير في النصر،\nده غير إنهم لما يخرجوا لهم عشان يقاتلوهم أفضل من إنهم ييجوا ويحاصروا المدينة، واحنا مش عايزين موقف الأخزاب يتكرر تاني\nوكمان في الموقف إللي احنا فيه ده القبائل دي مش هتبقى متوقعة إن رسول الله ﷺ يهجم عليهم لأنهم قبائل قوية ومعاهم الدولة الرومانية بتساعدهم،\nفكده فكده مش هيلحقوا يجمعوا أعداد كبيرة أوي يعني، طبعا كل ده من خلال تحليل الأمور على الأرض الواقع ساعتها،\nورسول الله ﷺ عارف كويس قوة القبائل العربية دي وعارف قوة الدولة الرومانية، عشان كده كان حريص جدا على تكوين جيش قوي يقدر يقوم بالمهمة دي على أكمل وجه\nعمل إيه بقى رسول الله ﷺ عشان يقدر يكوّن الجيش القوي ده\n◇أولاً: العدد\nكوّن رسول الله ﷺ أكبر جيش إسلامي خرج من المدينة لحد اللحظة دي، وكان عدد الجيش ثلاثة آلاف مقاتل وهو أكبر رقم يخرج للحرب في التاريخ الإسلامي لحد اللحظة دي.\n◇ثانياً: اختيار القائد\nخلى قائد الجيش ده الصحابي زيد بن حارثة رضي الله عنه، ولو تفتكروا، زيد بن حارثة كان قعد زي فترة تدريبية كده في السنة السادسة من الهجرة كان رسول الله ﷺ أخرجه\nفي ست سرايا ورا بعض وكان هو قائد السرايا دي،\nومننساش إن زيد بن حارسة كان قائد سرية 《حَسمى》 لقبيلة جُزام يعني هو كان عارف المنطقة أصلا وجاء فيها قبل كده\nورسول الله ﷺ مجعلش قائد واحد للسرية دي، جعل لها ثلاثة قادة ، يعني الأول زيد بن حارثة، وقال ﷺ لو قُتل زيد يتولى القيادة جعفر بن أبي طالب،\nولو قُتل جعفر يتولى القيادة عبد الله بن رواحة، ودي المرة الأولى والوحيدة إللي ولّى فيها رسول الله ﷺ ثلاثة أمراء على جيش واحد،\nولعل تولية الأمراء الثلاثة  كان بوحي من الله،\nبس بصفة عامة كان واضح إن رسول الله ﷺ يتوقع حرب شديدة بين المسلمين وبين الجيش إللي هيقابلهم في الشمال\n◇ثالثاً: إشراك خالد بن الوليد في الجيش.\nخالد بن الوليد قائد عبقري وكان قائد فرسان قريش، وعمره ما دخل معركة وانهزم سواء قبل إسلامه أو بعده،\nفلأن المعركة دي مش سهلة وهتبقى معركة شديدة أخرجه رسول الله ﷺ مع الجيش.\n☆ممكن ح يسأل يقول، طيب لما خالد بالقوة العسكرية دي ليه رسول الله ﷺ مخلهوش هو قائد الجيش\nخالد أسلم في شهر صفر، والجيش خرج في شهر جمادى الأولى، يعني خالد عمره في الإسلام ثلاثة أشهر فقط،\nوبالتالي هو ميعرفش جنود المسلمين وميعرفش طاقتهم إيه، ودي أول معركة له معاهم والمعركة دي مش سهلة،\nفكان لازم القائد يكون عنده خلفية إزاي يقاتل مع المسلمين وطريقة قتالهم إزاي وإيه هي قوانينهم،\nده غير إن خالد كان بقاله عشرين سنة بيقاتل في صفوف المشركين، فكان لازم يكون قائد الجيش له تاريخ مأمون مع المسلمين عشان يثقوا فيه وفي قراراته،\nوالثلاثة أمراء إللي اختارهم رسول الله ﷺ كلهم من السابقين الأولين للإسلام ولهم خبرة في القتال وكل المسلمين عارفينهم وعارفين فضلهم،\nفكان القرار الأمثل إن رسول الله ﷺ يُشرك خالد في القتال عشان يستفيد من خبراته القتالية من غير ما يكون هو القائد\nتجهز جيش المسلمين للخروج لمدينة مَعَان في الأردن، \nومع إن مهمتهم صعبة وهيقاتلوا عدو قوي وهيمشوا أكثر من ألف كيلو في صحراء والجو كان حر لأن خروجهم كان في شهر أغسطس؛ إلا إن الجيش كانت معنوياته عالية\nوعلى فكرة سفر ألف كيلو في الصحراء ده مش حاجة سهلة إطلاقا\nتخيلوا دلوقتي في عصرنا سفر ألف كيلو بعربية في طريق سهل ومتسفلت بيحتاج حوالي من عشر ساعات لاثنا عشر ساعة للوصول،\nوالسفر بيكون مرهق جدا أنا نفسي جربته، مع إني كنت في عربية مكيفة وقاعد مرتاح،\nفلكم أن تتخيلوا بقى دول هيمشوا في الصحراء في الحر ده من غير تكييف ولا مراوح وراكبين على جمال وخيول\nأنا بصراحة مش قادة أتصور كمية المشقة والتعب إللي كانوا فيها عشان يوصلوا للمكان ده\nوياريتهم مثلا هيوصلوا ويريحوا، لأ ده هيوصلوا ويحاربوا بالسيوف والرماح ويِجروا وهيبذلوا مجهود شديد جدا، وكل ده للدفاع عن الإسلام وعن دولة الإسلام في المدينة،\nوبعد كل ده يطلع لنا واحد ملوش أي لازمة يقول وهم الصحابة دول عملوا إيه يعني ويقعد يشتم فيهم ويقلل من شأنهم ومن مجهودهم\nالمهم،\nالجيش الخارج ده له مهمتين:\n◇المهمة الأولى:\nدعوة قبائل شمال شبه الجزيرة العربية للإسلام، فالهدف الرئيسي من كل الغزوات والسرايا هي نشر الإسلام،\nييجي بعدها بقى التأديب والدفاع عن دولة الإسلام أو الاقتصاص للصحابة إللي قُتلوا غدرا في معركة من المعارك،\nلكن الأصل هو الدعوة للإسلام.\n◇المهمة الثانية:\n قتال شُرحبيل بن عمرو الغساني وإللي عاونوه؛ لأنهم قتلوا رسول رسول الله ﷺ الحارث بن عمير رضي الله عنه زي ماقلنا.\nخرج رسول الله ﷺ بنفسه لثنية الوداع عشان يودع الجيش، وكان من عادة رسول الله ﷺ إنه يُوصي قائد الجيش إللي خارج لأي سرية بتقوى الله في نفسه وفي أصحابه إللي معاه ويوصيهم إنهم لا يقتلوا شيخ كبير في السن لو كان منعزل عن القتال،\nولا يقتلوا طفل ولا امرأة مُسالمة لا تقاتل، ولا يقطعوا الشجر، ولو قتلوا المقاتلين لا يُمثلوا بجثثهم، يعني بعد ما يموتوا ميقطعوش أي حاجة من أجسادهم،\nزي ما المشركين عملوا كده في شهداء أحد بعد المعركة، وقال لهم يجمعوا الغنائم ومحدش يَغُل منها حاجة يعني محدش ياخد حاجة من الغنائم ولا يخبيها قبل ما تتوزع\nالوصايا دي رسول الله ﷺ كان دايما يوصيها لأي قائد يخرج في سرية من السرايا،\nمع إن الحرب معروف فيها قتل الكبير والصغير والحرق والهدم، لكن الإسلام منع الكلام ده، \nالحرب كانت بتبقى بين الجيوش فقط مكنوش بيقتلوا أي حد ملوش علاقة بالقتال، وبالأخلاق دي الملسمين مَلكوا قلوب الناس،\nلأن الناس كانوا بيشوفوا نموذج من المقاتلين مشفهوش قبل كده\nانتم عارفين السبايا من النساء لما كان مثلا حد من قومهم ييجي يفديهم عشان يرجعهم لقومهم، وكان رسول الله ﷺ يسألهم ترجعوا لقومكم ولا تفضلوا مع المسلمين؟\nكانوا يرفضوا الرجوع لقومهم وكل واحدة تختار إنها تفضل مع سيدها\nفرسول الله ﷺ والصحابة ملكوا قلوب الناس بحُسن الخلق،\nوالتمكين في القلوب ييجي بعده التمكين في الأرض،\nيعني إللي عايز يدعي الناس والناس تستجيب له لازم يملك قلوبهم الأول، يعني يخليهم يحبوه\nوأقرب طريق لكسب قلوب الناس هو حسن الخُلق معاهم، وحسن الخلق يعني الواحد يتحمل أذاهم ويساعدهم ويخفف عنهم ويعاملهم معاملة حسنة من غير ما يستنى منهم أي مقابل،\nومهما الواحد تعرّض للأذى منهم يُقابل الأذى ده بإحسان ومعاملة طيبة ،زي ما كان رسول الله ﷺ بيعمل بالضبط\nيعني مرة رسول الله ﷺ كان ماشي في المدينة مع أنس بن مالك وكان رسول الله ﷺ لابس رداء غليظ، \nفجاءه واحد من الأعراب وشده من رداءه بقوة لدرجة إن ردائه أثّر في رقبته، يعني من قوة الشدة رقبة رسول الله ﷺ احمرت،\nفالأعرابي شد رسول الله ﷺ وقال له:\n\" يا محمَّد! مُرْ لي مِن مال الله الذي عندك\"\nيعني هو جاي يطلب صدقة، فبيقول لرسول الله ﷺ إن المال إللي هتدهولي ده مش مالك ده بتاع ربنا يعني انت مش بتتفضل عليّ بحاجة، \nتخيلوا كده لو حد فينا حصل معاه الموقف ده، حد شدنا في الشارع وطلب صدقة بالأسلوب ده، يا ترى هيكون رد فعلنا إيه؟!\nأقل شيء خالص إننا هنتضايق من أسلوب الطلب \nلكن رسول الله ﷺ كان رد فعله مختلف تماما\nرسول الله ﷺ التفت للأعرابي وضحك له وأمر له بعطاء، كده بكل بساطة من غير عتاب ولا زعل ولا حتى ظهر على وجهه ﷺ أي علامة من علامات الغضب\nعشان كده رسول الله ﷺ كان بيأسر قلب أي حد يتعامل معاه، ولأن هو القدوة فمحتاجين نتعلم ده منه ﷺ\nنرجع للجيش،\nالجيش تجهز ورسول الله ﷺ أوصى القائد بالوصايا وخلاص خارجين، وفجأة القائد الثالث للجيش عبد الله بن رواحة بدأ يبكي بكاء شديد\nفالناس فكروا إنه بيبكي عشان خايف من الموت، فسألوه:\nما يُبكِيك يا ابن رواحة؟\nفقال لهم:\n\"والله ما بي حبُّ الدنيا ولا صَبابَةً بكم، ولكني سمعت رسول الله ﷺ يقرأ آية من كتاب الله يذكر فيها النار\"\nيعني بيقول لهم أنا مش خايف من الموت، ولا خايف من البعد عنكم، لكن أنا خايف إن يكون مصيري النار، \nيقول عبد الله بن بن رواحة : ولكني سمعت سمع رسول الله ﷺ يقرأ قول الله عز وجل:\n\"وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا\"\n☆خلونا نعرف معنى الآية عشان نفهم ليه عبد الله بن رواحة كان خايف\nالآية معناها إن كل من ينتسب للإسلام هيعدي على النار، طبعا المشركين والكفار  هيكونوا في النار أصلا مش محتاجين يعدوا على النار،\nلكن كل واحد ينتسب للإسلام هيعدي على الصراط إللي هيكون فوق جهنم حتى الأنبياء والرسل هيعدوا من على الصراط ده،\nففي إللي هيعدي على الصراط كلمح البصر، وفي إللي هيعدي بسرعة البرق وفي إللي هيعدي زي الريح وفي إللي هيجري بيه عمله زي إللي راكب على حصان سريع،\nوفي بقى إللي هيقع في النار لشدة وكثرة معاصيه، فكلنا كده بلا استثناء هنعدي على النار،\nأهل الإيمان والتقوى هيعدوا عليها من غير ما تؤذيهم ولا تضرهم، وربنا هينجيهم منها، زي ما قال في الآية إللي بعدها:\n\"ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوا وَّنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا\"\nفعبد الله بن رواحة تذكر الآية وقعد يبكي وخايف إنه لما يموت ويعدي على جهنم يقع فيها وميخرجش منها،\nقال:\n\"فلستُ أدري كيف لي بالصّدُور بعد الورود\"\nتخيلوا إن إللي بيقول كده واحد من أصحاب بيعة العقبة الثانية، \nواحد جاهد مع رسول الله ﷺ وحضر معاه كل الغزوات، بدر وأحد والأحزاب وكمان من أهل بيعة الرضوان إللي رسول الله ﷺ شهد لهم بالجنة،\nومش بس كده ده كان بيدافع بشعره عن الإسلام، يعني مجاهد باللسان وبالسيف ومع كل ده خايف إنه يقع في النار وميخرجش منها\n☆ممكن حد هنا يسأل سؤال ويقول، طب ليه هو خايف مع إن ربنا كريم وبيضاعف الحسنات، ولا يضيع أجر المحسنين،\nفليه يخاف الخوف ده كله\nإللي يجاوبنا على السؤال ده الحوار إللي حصل بين السيدة عائشة رضي الله عنها ورسول الله ﷺ،\nالسيدة عائشة سألت رسول الله ﷺ عن آية:\n\"وَالَّذِينَ يُؤْتُونَ مَا آتَوْا وَقُلُوبُهُمْ وَجِلَةٌ\"\nأَهُمْ الَّذِينَ يَشْرَبُونَ الْخَمْرَ وَيَسْرِقُونَ؟!!\nيعني الناس إللي خايفة وقلقانة دي هم أصحاب المعاصي زي إللي بيشربوا الخمر ويسرقوا،\nفبسبب ذنوبهم  إللي بيعملوها دي بقى في قلوبهم خوف من ربنا؟!\nفرسول الله ﷺ رد عليها وقال لها:\n\"لَا يَا بِنْتَ الصِّدِّيقِ !\nوَلَكِنَّهُمْ الَّذِينَ يَصُومُونَ وَيُصَلُّونَ وَيَتَصَدَّقُونَ وَهُمْ يَخَافُونَ أَنْ لَا يُقْبَلَ مِنْهُمْ أُولَئِكَ الَّذِينَ يُسَارِعُونَ فِي الْخَيْرَاتِ\"\nيعني الناس إللي خايفة دي هم الطائعون إللي بيصوموا ويتصدقوا ويعملوا الصالحات وبيسابقوا في عمل الخير لكن خايفين من إن ربنا ميتقبلش عملهم،\nوهي عادة الصالحين، كل ما كان الإنسان طائع كل ما كان خوفه من ربنا ومن سوء الحساب يوم القيامة أكثر\nلأنه بيكون عارف عظمة ربنا وعارف إنه مهما عبد ربنا وعمل الصالحات فمش هيوفي نعمة واحدة بس من نِعم ربنا عليه،\nوطبعا يا جماعة المقصود بالخوف هنا هو الخوف إللي يدفع الإنسان للعمل الصالح مش الخوف إللي يوصل الإنسان إنه يقنط من رحمة ربنا ويُوقفه عن العمل\nيعني عبد الله بن رواحة رضي الله عنه كان خايف من ربنا بس في نفس الوقت خوفه ده مخلاهوش يتوقف عن الأعمال الصالحة زي خروجه للجهاد في سبيل الله مثلا،\nفالإنسان مطلوب منه إنه يخاف من ربنا ويخاف من عذابه لكن يبقى في نفس الوقت عنده حسن ظن بالله إن ربنا هيتقبل حسناته وأعماله الصالحة،\nولأنه مش عارف بالضبط أنهو عمل صالح إللي ربنا هيتقبله منه فهو بيعمل أعمال صالحة كتييير\nوزي ما قال الفُضَيْل بن عِيَاض:\n\"من خاف الله دلَّه الخوفُ على كل خير\"\nيعني إللي بيخاف ربنا بجد هو ده إللي خوفه هيساعده ويدله لعمل كل خير،\nأما بقى الناس إللي غرقانة في المعاصي ومستمرين فيها ولا يُلقوا لها بالا ومش في دماغهم،\nوبالنسبة لهم المعاصي دي حاجة عادية وربنا غفور رحيم بقى واحنا كفاية إننا مسلمين والكلام ده، فللأسف الناس دي عايشة في غرور ووهم\nعايزين كده حد يقولهم على فكرة الجنة هيدخلها المتقون، وإللي هيقدر يعدي على الصراط هم إللي بيتقوا ربنا وبيخافوا من عذابه وبيسارعوا في عمل الصالحات\nبعد ما عبد الله بن رواحة قال لهم على سبب بكائه الناس الحاضرين وكانوا بيودعوا الجيش مع رسول الله ﷺ قالوا له:\n\" صَحِبَكم الله ودفع عنكم، وردّكم إلينا صَالِحين غانمين\"\nلكن دي مكنتش أمنية عبد الله بن رواحة، هو مكنش عايز يرجع سالم غانم، هو كان عايز يموت شهيد في سبيل الله،\nفقال أبيات شعر تعبر عن أمنيته: \nلَكِنَّنِي أَسْأَلُ الرَّحْمَنَ مَغْفِرَةً **وَضَرْبَةً ذَاتَ فَرْعٍ تَقْذِفُ الزَّبَدَا \nيعني بيدعي ويتمنى من ربنا إنه يغفر له ويرزقه بواحد يضربه بالسيف ضربة شديدة جدا تُفجّر الدم من جسمه ويموت شهيد.\nخرج الجيش باتجاه مدينة مَعَان في الأردن، طبعا قعدوا وقت طويل على ما وصلوا والرحلة كانت شاقة عليهم،\nلما وصلوا لقوا قصادهم مفاجأة غير متوقعة\nالقبائل في شمال الجزيرة العربية جمعت مائة ألف مقاتل لحرب المسلمين\nومش كده وبس، ده الدولة الرومانية أرسلت هي كمان مائة ألف مقاتل عشان يساعدوا القبائل العربية المُتنصرة الحليفة لهم،\nيعني بقى عندنا دلوقتي جيش مكون من مائتين ألف مقاتل من المشركين، وجيش المسلمين ثلاثة ألاف بس\n☆ثواني كده، هو إزاي رسول الله ﷺ يُخرج جيش صغير كده لقتال مئتين ألف؟ مش المفروض إنه كان يعمل حسابه؟ وكمان مش كده يُعتبر إلقاء بالنفس للتهلكة\nهو الجيش الإسلامي إللي كان خارج ده مكنش هدفه قتال الدولة الرومانية أصلا،\nوكمان كان من المتوقع إسلام الدولة الرومانية أو على الأقل هيكونوا على الحياد ومش هيشاركوا في قتال المسلمين،\nأيوة كان احتمال مساعدة منهم بس مش بالصورة دي،\nوالكلام ده كان على أساس المعاملة الطيبة إللي هرقل عاملها لدحية الكلبي رسول رسول الله ﷺ لما جاءه برسالته ﷺ وكمان هرقل أظهر اقتناعه بالإسلام،\nفكانت كل المؤشرات بتقول إن الدولة الرومانية مش هتتدخل في القتال بين المسلمين وبين القبائل العربية في الشمال،\nفالجيش ده كان متوجه لحرب مجموعة معينة بقيادة شرحبيل بن عمرو الغساني،\nومكنش من عادة القبائل العربية إنهم يتحدوا ويقاتلوا مع بعض في أعداد كبيرة من الأساس، العرب كانوا قبائل متفرقة كلهم بيهجموا على بعض،\nفجيش المسلمين يعتبر جيش كبير أصلا في الفترة الزمنية دي، ومكنش من المتوقع إن الجيش الإسلامي هيواجه جيش أكبر منه أوي في العدد، وخصوصا إنهم تغلبوا قبل كده على عشرة آلاف في غزوة الأحزاب،\nفطبعا العدد ده مكنش متوقع أبدا لا من رسول الله ﷺ ولا من الصحابة\nطبعا محدش يسأل ويقول طيب وهو ليه ربنا مأخبرش رسول الله ﷺ بالأعداد دي عن طريق الوحي قبل ما المسلمين يخرجوا \nلأن لو ربنا أخبر رسول الله ﷺ عن طريق الوحي دلوقتي، المسلمين هيعملوا إيه بعد كده لما يتحطوا في نفس الموقف ده ومفيش وحي\nوحصل فعلا في فتوحات فارس والروم إن أعداد الجيش الفارسي والروماني كانت أضعاف أضعاف المسلمين،\nفكان لازم المسلمين يخوضوا التجربة دي دلوقتي ورسول الله ﷺ موجود عشان يعرفوا إزاي هيتصرفوا ورسول الله ﷺ هيقرهم على فعلهم ده ولّا لأ\nطيب إزاي بقى الصحابة اتصرفوا في الموقف ده، وإيه القرار إللي أخدوه؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 180, "l": "الجزء 154 | احداث السنه الثامنه من الهجرة | احداث معركة مؤته", "u": "https://www.facebook.com/groups/710210019782034/permalink/836540480482320/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وأربعة_وخمسون\n#أحداث_السنة_الثامنة_من_الهجرة\n#أحداث_معركة_مؤتة\nوقفنا المرة إللي فاتت عند وصول جيش المسلمين لمدينة مَعَان الأردنية إللي لقوا متجمع فيها حوالي مائتين ألف مقاتل من قبائل العرب في شمال الجزيرة العربية ومن الدولة الرومانية، \nالصحابة اتفاجؤوا بالعدد الكبير إللي مكنوش متوقعينه، فعملوا زي مجلس استشاري كده عشان يشوفوا إيه أفضل حل ممكن يعملوه،\nقبل ما نعرف الحلول إللي الصحابة اقترحوها عايزين نعرف ليه الرومان جمعوا الأعداد دي كلها لقتال المسلمين\nقلنا المرة إللي فاتت إن العرب مكنش من عادتهم إنهم يتجمعوا ولا يتوحدوا ويقاتلوا تحت راية واحدة ده بالعكس كانوا بيقاتلوا بعض،\nلكن معنى إنهم يتجمعوا ويكوّنوا جيش من مائة ألف مقاتل فده أكيد بأمر من هرقل ملك الروم،\nلأن القبائل والدول العربية مش بتتحرك وقت القتال إلا لما تاخد الإذن من القائد الأعظم للدولة الأولى في العالم،\nساعتها الكل يتجمع\nفكان الهدف من التجميع الكبير ده إنهم يقضوا على الإسلام تماما، يعني مش مجرد إنهم يكسبوا معركة وخلاص، لأ، ده عايزين يُبيدوا جيش المسلمين تماما،\nيعني هرقل عارف كويس جدا إنه بيحارب نبي، ففكر إنه لما يجمع جيش بقوة خارقة وبأعداد كبيرة ممكن يغلب جيش النبي ده،\nده غير إنهم مكنوش عارفين عدد جيش المسلمين بالضبط أد إيه فكوّنوا جيش كبير جدا مهما المسلمين جمّعوا من أعداد فمش هييجي حاجة جنب الجيش إللي الدولة الرومانية جمعته\nنشوف بقى إيه الآراء إللي الصحابة اقترحوها عشان يخرجوا من الأزمة دي:\n◇الرأي الأول:\nإن المسلمين يرسلوا رسالة لرسول الله ﷺ في المدينة يخبروه بأن الأعداد كبيرة جدا، وهو إللي يحدد بقى يعملوا إيه، هل يُرسل لهم مدد ولّا يأمرهم بالقتال، ولّا يأمرهم بالانسحاب،\nلكن الرأي ده مكنش واقعي وكان صعب تنفيذه؛ لأن عشان واحد يروح لرسول الله ﷺ في المدينة يخبره بالرسالة محتاج إسبوعين رايح وأسبوعين جاي، \nيعني الجيش هيستنى شهر كامل قبل ما ياخدوا أي قرار وده مستحيل طبعا، يعني لو جيش المسلمين استنى، فجيش الكفار مش هيستناهم\n◇الرأي الثاني:\nإن زيد بن حارثة رضي الله عنه قائد الجيش ينسحب بالجيش وميدخلش في أي قتال، وأصحاب الرأي دول قالوا  لزيد بن حارثة:\n\"قد وطِئت البلاد وأخفت أهلها فانصرف، فإنه لا يعدل العافية شيء\"\nيعني هم شايفين إن الحرب دي مُهلكة لهم، وجيش المسلمين سمّع الناس عنه وعن الإسلام فخلاص خلينا ننسحب\n◇الرأي الثالث:\nإنهم يدخلوا المعركة بدون أي تردد ويواجهوا الأعداد كلها،\nوكان صاحب الرأي ده هو عبد الله بن رواحة رضي الله عنه،\nوقالهم بكل وضوح:\n\"يا قوم!\nوالله إن التي تكرهون لَلّتي خرجتم تطلبون،\nوما نقاتل الناس بعدد ولا قوة ولا كثرة، ما نقاتلهم إلا بهذا الدين الذي أكرمنا الله به، فانطلقوا، فإنما هي إحدى الحُسْنيين: إما ظهور، وإما شهادة\"\nيعني هو انتم خرجتم للجهاد ليه، مش عشان عايزين الشهادة في سبيل الله؟ طيب لما الشهادة جت لكم لحد عندكم بقيتم كارهينها؟! ده هي دي إللي احنا خارجين عشانها أصلا\nواحنا مش بنقاتل الناس بالعدد ولا بالقوة ولا بالكثرة لكن بنقاتلهم بالعقيدة وقوة تمسكنا بالدين،\nفخلونا نقاتل والنتيجة هتكون حاجة من اتنين نتمناهم إما النصر أو الشهادة\nطبعا مش معنى الكلام إن المسلمين يتركوا الاستعداد للمعركة \nلأ، هم يعملوا ويقدموا إللي يقدروا عليه وربنا هينصرهم، وربنا قال:\n\"وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ وَمِنْ رِبَاطِ الْخَيْلِ تُرْهِبُونَ بِهِ عَدُوَّ اللَّهِ وَعَدُوَّكُمْ \"\nفلما عبد الله بن رواحة قال كلامه ده كل الصحابة قالوا:\nصَدق والله ابن رواحة\nوأجمعوا كلهم على القتال والدخول في المعركة.\n☆سؤال بقى: هل قرار الحرب إللي الصحابة أخدوه ده كان قرار صحيح ولّا لأ\nقرارهم كان صحيح تماما\nبدليل إن بعد ما الجيش رجع بعد المعركة رسول الله ﷺ معاتبهمش ومعلقش أي تعليق سلبي على قرار حربهم ده ،\nولا قالهم إنه كان الأولى والأحسن إنهم ميقاتلوش،\nورسول الله ﷺ لا يسكت عن منكر أبدا وكل حاجة هو بيشوفها وبيُقرها فهي سنة ومن الدين\nومننساش إنه كان في جيش المسلمين عقليات حربية كبيرة زي خالد بن الوليد رضي الله عنه،\nوهو عبقري أصلا فلو كان شاف إن قرار الحرب هيهلك الجيش كله كان هيعترض ويتكلم ويقول وجهة نظره، وخصوصا إن الكل عارف إن الجيش الإسلامي ده مش مِلك لأفراد بعينهم يضحوا بيه زي ما هم عايزين، ده ملك للدولة الإسلامية لازم القادة يحافظوا عليه\nوأه الشهادة شرف وأجرها عظيم لكن لو غلب على ظن قائد الجيش إن جيشه هيَهلك كله لو دخل في معركة يبقى مينفعش يدخل المعركة دي بالعكس ده يبقى دخوله فيه مفسدة، ومينفعش شرعا؛ لأن إزاي يضحي القائد بثلاثة آلاف مقاتل هم عمود الدولة الإسلامية في الوقت ده\n☆سؤال تاني، \nإزاي الصحابة شافوا إنهم عادي كده يواجهوا مائتين ألف، وشافوا إن الجيش فعلا مش هيَهلك، \nيعني هم إيه إللي خلاهم يفكروا كده\nعندنا احتمالين:\n◇ الاحتمال الأول:\nإن المسلمين مكنوش يعرفوا بالضبط عدد الجيش إللي هيقاتلوه ده أد إيه، \nيعني هم شافوا أعداد كبيرة فقدّروهم بإنهم خمسة أو عشرة أضعافهم أو أكثر أو أقل بحاجة بسيطة، فلقوا إن القتال مع الأعداد دي هيبقى صعب لكنه مش مستحيل، وربنا قال لهم في القرآن:\n\"كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللَّهِ\"\nوالآية دي لو تفتكروا في قصص الأنبياء كانت بتتكلم عن أتباع طالوت إللي قاتلوا معاه الجبابرة وانتصروا عليهم في الآخر مع إن عددهم كان أقل بكثير من الجبابرة وقوتهم كانت أقل،\nفالصحابة كانوا بيحوّلوا القرآن لواقع عملي، هم عارفين قصة طالوت وهم بنفسهم جربوا لما كانوا في غزوة بدر وغزوة أحد قبل معصية الرماة لأمر رسول الله ﷺ،\nوجربوا كذلك في الأحزاب، ده غير إن ربنا قال لهم في سورة الأنفال إللي نزلت بعد غزوة بدر إن الجيش المؤمن قادر على مواجهة عشرة أضعافه لو كان قوي الإيمان بجد\n\"إِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صَابِرُونَ يَغْلِبُوا مِائَتَيْنِ وَإِنْ يَكُنْ مِنْكُمْ مِائَةٌ يَغْلِبُوا أَلْفًا مِنَ الَّذِينَ كَفَرُوا\"\nفهم عارفين إن الموضوع مش بالعدد لكن بقوة الإيمان\n◇الاحتمال الثاني:\nهو إن قادة المسلمين شافوا إن الانسحاب مش هينجيهم من جيوش التحالف الرومانية العربية،\nوإن الجيش الإسلامي لو بدأ ينسحب ويتراجع فممكن جيش الكفار يحاصره من كل الجهات، وفي الحالة دي هتبقى مجزرة فعلا في جيش المسلمين\nفي حين بقى إن الثبات والمقاومة هم الأفضل\nليه\nلأن ده هيُعطي دَفعة نفسية إيجابية للجيش المسلم في إنه يهاجم ويخطط لهزيمة جيش الكفار بدل من إنه يفكر في الهرب والدفاع فقط،\nوأفضل طريقة للدفاع هي الهجوم\nفهم شافوا إن مفيش أي أمل ولا نجاة لو انسحبوا، ولازم مواجهة عشان يخرجوا من القتال ده بأقل الخسائر الممكنة،\nومش بس كده، ده قوات التحالف الرومانية العربية هيتفاجؤوا وتهتز معنوياتهم لما يشوفوا جيش بيطلب الموت ومش فارق معاه حاجة، بعكس جيش التحالف العربي الروماني إللي حريص جدا على الحياة لأنه شايف إن هي دي الحياة بتاعته ومش هيعيش غيرها\nبعد ما أخذ المسلمون قرار الحرب، اتوجهوا لاختيار أرض المعركة عشان يكون الاختيار في صالحهم مش في صالح جيش الكفار،\nجيش المسلمين توجه ناحية 《مُؤْتَة》، ومنطقة مؤتة في الأردن جنوب محافظة الكَرك في زماننا دلوقتي.\n☆اشمعنى بقى الصحابة اختاروا المكان ده بالذاااات\nماحنا قلنا إن الجيش كان فيه عقليات حربية كبيرة، فالعقليات دي مش هتختار أي مكان كده وخلاص \nشوفوا بقى،\nمكان معركة مؤتة عبارة عن سهل مُنبسط مفهوش جبال ولا عوائق طبيعية من مياه أو أشجار أو أي شيء، وفيه مزايا هتسهل على المسلمين عملية القتال\nإزاي\n◇أولا:\nكون إن المكان سهل ومُنبسط ده هيحرم الفريقين من المُناورة أو المراوغة يعني محدش يلف من وراهم مثلا ويهجم عليهم، وكمان بيمنع الفريقين إنهم يعملوا كمائن، وإلا لو استطاع الرومان إنهم يعملوا كمائن كانت هتبقى مصيبة على جيش المسلمين\n◇ثانياً:\nمنطقة مؤتة عبارة عن أرض صحراوية، والعرب متعودين على القتال في الأرض الصحراوية، بخلاف الجيوش الرومانية التي متعودة على القتال في الأراضي الخضراء في الشام وفي تركيا وفي الأراضي كثيرة الأشجار.\n◇ثالثاً:\n السهل مفتوح من جنوبه على الصحراء الواسعة، فالرومان مش هيقدروا يتجرؤوا على التوغل في الصحراء دي، وبكده يقدر الجيش الإسلامي إنه ينسحب إذا أراد الانسحاب.\n◇رابعاً:\nفي جنوب السهل خلف الجيش الإسلامي في بعض التلال، فممكن الجيش الإسلامي يستغل التلال دي في إخفاء نفسه وراءها لو أراد الانسحاب في الليل.\n◇خامساً:\nلأن السهل ده مفهوش أي عوائق طبيعية فمفيش أي نوع من الحماية للجندي إلا إنه يحتمي وراء سيفه ودرعه، \nوبالتالي المكان المفتوح ده هيظهر أثر الشجاعة والإقدام، والنقطة دي بالذات يتفوق فيها الصحابة على غيرهم بدون أي شك\nلأن المسلمين بيقاتلوا لقضية مهمة وهدفهم هدف نبيل وهو الدفاع عن الإسلام ونشره أو الشهادة في سبيل الله،\nبعكس الجيش الروماني إللي جاي عشان بس ينفذ أمر الحاكم بتاعه، وهم مش هيستفيدوا أي حاجة،\nهم إللي هيدفعوا أرواحهم تمن الهزيمة، أما لو انتصروا فاللي هيسعد بالنصر ده هو الحاكم والقادة بتوعه\nاستقر المسلمون في منطقة مؤتة وبدأت أمواج بشرية من الرومان والعرب تدخل أرض المعركة،\nوبدأ القتال بين الفريقين بقيادة حامل الراية زيد بن حارثة رضي الله عنه،\nفي الوقت ده في المدينة كان رسول الله ﷺ نادى في الناس عشان يجتمعوا،\nفلما اجتمع الناس بدأ رسول الله ﷺ يحكي للناس إللي بيحصل في أرض المعركة، وده من معجزات رسول الله ﷺ،\nكان في المدينة وبيحكي إللي بيحصل في أرض المعركة إللي على مسافة أسبوعين\nقال لهم إن زيد حمل الراية وانطلق للقتال،\nوكان زيد فعلا انطلق ناحية الجيش الروماني والمسلمين وراءه وفي ثواني الدنيا اتملت غبار ومبقاش مسموع في أرض المعركة إلا أصوات السيوف أو صرخات الألم، \nويتخلل الأصوات دي صوت تكبيرات المسلمين أو بعض الأبيات الشعرية إللي بتحمس المسلمين للقتال والثبات،\nوبدأ المسلمون يقتلوا في الروم، \nواشتد القتال بين الفريقين وكان ده أشد قتال مر على المسلمين لحد اللحظة دي\nوسقط أول شهيد في أرض المعركة وهو زيد بن حارثة رضي الله عنه، حامل الراية وحِب رسول الله ﷺ،\nسقط بعد رحلة طويلة مع الإسلام ومع الصبر على الأذى وعلى الجهاد في سبيل الله، فهو كان أوائل المسلمين لو تفتكروا كان هو أول من أسلم من الموالي،\nوكان هو إللي راح مع رسول الله ﷺ للطائف، أنا عايزاكم تتخيلوا التاريخ ده كله والمشاعر دي كلها ورسول الله ﷺ بيشوفه وهو بيُقتل قصاد عينه\nما هو رسول الله ﷺ شايف أحداث المعركة وشايفه وهو عمال بياخد الطعنات في جسمه لحد ما سقط شهيد،\nورسول الله ﷺ بيقول لأهل المدينة إن زيد استشهد ودموعه ﷺ تنزل على خده\nمهما حاولنا نوصف مشاعر الحزن إللي كان رسول الله ﷺ بيحس بيها في اللحظة دي مش هنقدر بجد\nوالألم موقفش عند النقطة دي، بعد ما سقط زيد شهيدا أخذ الراية جعفر بن أبي طالب رضي الله عنه القائد الثاني للجيش وانطلق يُقاتل في الجيش الروماني وهو كمان بدأت تنزل عليه الطعنات،\nومن شدة القتال نزل من على فرسه وقتلها عشان الفرس ميهربش وهو راكب عليه، \nوانطلق يقاتل في الروم لحد ما اتصاب بأكثر من خمسين طعنة سيف ورمح، \nوكان يحمل الراية بإيده اليمين فضربه واحد من جيش الكفار على إيده اليمين فقطعها،\nفمسك الراية بإيده الشمال، فقُطعت فمسك الراية بعضديه، يعني الحتة إللي عند الكتف من فوق دي، فاجتمعوا عليه وقتلوه رضي الله عنه وهو ماسك الراية عشان يحميها من إنها تقع،\nكل ده ورسول الله ﷺ شايف وبيحكي للناس في المدينة وهو يبكي ﷺ \nربنا أبدل يدي جعفر رضي الله عنه إللي اتقطعت دي بجناحين في الجنة يطير بيها حيث يشاء\nأيوة في آلام في الدنيا لكن كل ده هيتعوض في الآخرة للي يصبر على الابتلاء والألم مش يستسلم لأي ابتلاء وقع له،\nوغمسة واحدة في الجنة تُنسى أشد الناس بُؤسا في الدنيا أي شدة أو بؤس شافها، \nلكن الصبر يا جماعة الصبر، الدنيا دي ساعة بالنسبة للآخرة نستحملها لحد ما الدنيا تعدي\nبعد ما قُتل جعفر، أخذ الراية القائد الثالث عبد الله بن رواحة رضي الله عنه إللي كان بيحمّس المسلمين لمواجهة الكفار، وانطلق يقاتل في الرومان زي جعفر وزيد رضي الله عنهم أجمعين،\nواستمر يقاتل رضي الله عنه لحد ما قُتل شهيد هو كمان، والناس تسمع من رسول الله ﷺ إللي بيحصل وبيبكوا على قتل إخوانهم،\nطبعا يا جماعة الحزن والبكاء لا يتعارض مع الإيمان ولا الصبر، الحزن على فراق حد بنحبه ده شيء طبيعي وعادي،\nلكن مينفعش نتسخط ولا نعترض على قضاء ربنا وإللي يصبرنا على فراق مَن نحب إننا نتذكر إن إللي عند ربنا خير وأبقى وإن الحياة الآخرة هي فعلا الحياة الحقيقية\n☆في هنا ملحوظة مهمة :\nفي رواية بتقول إن عبد الله بن رواحة رضي الله عنه لما أخذ الراية تردد في القتال، يعني مبقاش عايز يكمل القتال وخاف، وبعدين شجع نفسه وقعد يقاتل لحد ما قُتل،\nوإن بسبب التردد بتاعه ده منزلته في الجنة أقل من منزلة جعفر وزيد رضي الله عنهم جميعا،\nلكن الكلام ده غير صحيح نهائي، والرواية دي منقطعة ولا تصح\nوحتى بالعقل يعني الرواية دي بتتعارض مع روايات تانية صحيحة في إنه كان بيتمنى الشهادة وهو إللي حمس الجيش لعدم الانسحاب والتقدم للقتال\nطبعا النقطة دي فيها تفصيل وإللي عايز يعرف الرواية بالأسانيد وليه الرواية ضعيفة يراجع كتاب :\n《ما شاع ولم يثبت في السيرة النبوية》أو يشوف الرابط في التعليقات\nبعد استشهاد عبد الله بن رواحة انطلق نحو الراية واحد من المسلمين وحمل الراية\nمين إللي أخذ الراية وياترى موقف المسلمين هيكون إيه بعد هزيمة القادة الثلاثة،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 181, "l": "الجزء 155 | احداث السنه الثامنه من الهجرة | الأحداث بعد معركة مؤته", "u": "https://www.facebook.com/groups/710210019782034/permalink/836540600482308/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وخمسة_وخمسون\n#أحداث_السنة_الثامنة_من_الهجرة\n#الأحداث_بعد_معركة_مؤتة\nوقفنا المرة إللي فاتت عند مقتل الثلاثة قادة لجيش المسلمين وتقدم واحد من المسلمين من حملها،\nراية المسلمين لم تسقط في أرض المعركة،\nفالصحابة كانوا حريصين على إن الراية تفضل مرفوعة لأنها لو سقطت هيتزعزع جيش المسلمين وينهزم،\nفالراية لم تسقط ولا مرة واحدة في أرض معركة مؤتة، مش زي مانا قلت في آخر الجزء إللي فات إنها سقطت وبعدين واحد من الصحابة حمل الراية، \nمعلش أنا كنت اتلغبطت وخلاص عدّلت الجملة دي في الجزء إللي فات وبقولكم دلوقتي عشان إللي كان قرأها يصحح المعلومة\nفاللي حصل إن الراية فضلت واقفة وبعد ما قُتل عبد الله بن رواحة حمل الراية على طول الصحابي 《ثابت بن أَقْرم》 عشان متسقطش، \nوهو من الصحابة إللي حضروا غزوة بدر، وحضر الغزوات كلها مع رسول الله ﷺ،\nفلما أخذ الراية قال للمسلمين إنهم يختاروا واحد منهم يكون هو القائد،\nفقالوا له انت القائد، فقال لهم إن في ناس أفضل منه في المجال ده وتقدم ناحية خالد بن الوليد وأعطاه الراية وقال له : أنت أعلمُ بالقتال مني\nفقال له خالد بن الوليد:\n\"أنت أحق بها مني، أنت شهدت بدراً\"\nيعني انت إللي تستاهل قيادة الجيش عشان انت حضرت بدر وأهل بدر هم أفضل الناس، \nلكن الموضوع هنا مش مين إللي من حقه ياخد الراية، احنا بنتكلم عن الأعلم وإللي معاه المصلحة،\nأيوة《الأحق》 هو ثابت بن أقرم، لكن مين\n《الأعلم بالقتال》 ويقدر يقود الجيش؟!\nطبعا خالد بن الوليد، فاجتمع المسلمون ورضوا بقيادة خالد وأعطوه الراية، وأول ما أخذ الراية قال رسول الله ﷺ للمسلمين في المدينة :\n\"حتى أخذ الراية سيف من سيوف الله ففتح الله عليه\"\nيعني رسول الله ﷺ بيوصف خالد بن الوليد بالشجاعة لأن السيف رمز للقوة والشجاعة، وأضافه لاسم الله من باب التشريف لخالد، يعني زي ما بنقول بيت الله وناقة الله،\nفخالد هو سيف الله،\nفأخذ خالد الراية وانطلق يقاتل جيش الرومان والمسلمين وراه،\nوده أول قتال يحضره خالد بعد إسلامه، فقعد يقاتل قتال شديد وكأنه عايز يكفر عن العشرين سنة إللي فاتت إللي كان بيحارب فيها الإسلام،\nومن شدة قتاله انكسر في إيده تسعة أسياف، يعني فضل يقاتل بالسيف لحد ما كان السيف يتكسر وياخد غيره وهكذا لحد ما اتكسرت التسع أسياف، ومتبقاش في إيده غير سيف يمني عريض زي الصفيحة كده،\nفتخيلوا بقى قتل ناس أد إيه\nاستمر القتال لحد الليل،\nأول ما جاء الليل انسحب كل فريق للمعسكر بتاعه، وكان قتال الناس زمان طول اليوم وأول ما ييجي الليل يتوقف القتال،\nلأن الدنيا بتكون ضلمة ومحدش شايف حاجة فممكن واحد يقتل صاحبه إللي معاه من الجيش وهو مش شايفه،\nوتتحول المعركة بدل ما هي قتال للأعداء تبقى قتال بين الجيش الواحد\nالروم كان حصل فيهم مقتلة عظيمة، ومع إن عدد المسلمين كان قليل بالنسبة لعدد جيش الكفار لكن المسلمين أتْعَبوا الجيش الروماني جدا وكانوا مذهولين من قوة المسلمين وشجاعتهم وقتالهم،\nفكان الليل فرصة لهم إنهم يستريحوا من القتال، لكن الوضع في معسكر المسلمين كان مختلف،\nخالد قائد الجيش دلوقتي قرر إنه ينسحب بالمسلمين لأن الأولوية دلوقتي الحفاظ على الجيش، ومهما قتل المسلمون من الرومان فأعدادهم مش بتنتهي،\nفهو شاف إن أفضل قرار دلوقتي هو الإنسحاب، لكن الإنسحاب هو أخطر خطوة ممكن يعملها أي جيش، لأن الإنسحاب أو الهرب من أرض المعركة هيعرّض الجيش كله للقتل،\nلأن جيش العدو هيخرج وراء المنسحب ده ويقعدوا يقتلوا فيهم أو يأسروهم، \nفكان لازم خطة للإنسحاب متعرضش جيش المسلمين للخطر، ففكر خالد في خطة للإنسحاب وبدأ بتفيذها\nإيه بقى الخطة دي\nفي الأول كده الرواية إللي ذَكرت خطة خالد هي رواية ضعيفة،\nلكن هي دي الرواية الوحيدة إللي اتكلمت عن خطة خالد بن الوليد وكل كتب السّيَر بتقولها، وممكن تراجعوا كتاب:\n《ما شاع ولم يثبت في السيرة النبوية》\nفأنا هقول الخطة دي من باب العلم بالشيء يعني،\nومش هتضرنا في حاجة لو قلناها لأنها خطة ممتازة بصفة عامة، ويمكن يكون لها أصل، الله أعلم\nفخلونا بقى نشوف إيه الخطة إللي اتقال إن خالد بن الوليد رضي الله عنه عملها، \n¤أولا : \nخطة خالد كان الهدف منها إن الرومان يحسّوا إن المسلمين جالهم مَدد من المدينة، والمدد يعني جيش تاني جاء لمساعدة الجيش الموجود،\nوبالتالي جنود الرومان والعرب المتحالفين معهم هيحسوا بالإحباط والخوف والذعر؛ \nلأنهم كانوا صامدين بصعوبة كبيرة جدا قصاد الثلاثة آلاف ومش قادرين عليهم ومقتلوش منهم إلا كم واحد، فلما كمان ييجي لهم مدد هيحصل فيهم إيه\n¤ثانيا: عشان خالد يحقق الهدف ده عمل أربع خطوات:\n◇الخطوة الأولى:\nخلّى الخيل أثناء الليل تجري في أرض المعركة، عشان تُثير الغُبار الكثير، فالرومان هيتهيأ لهم إن في مدد جاء للمسلمين في الليل.\n◇الخطوة الثانية:\nالجيش كان متقسم لمَيمنة ومَيْسرة ومُقدمة ومؤخرة،\nفخالد غيّر أماكن المسلمين،\nيعني خلّى الميمنة ميسرة والميسرة ميمنة، وخلّى المقدمة مؤخرة والمؤخرة مقدمة،\nفلما جاء وقت القتال ووقف الجيشين قصاد بعض الرومان بقوا شايفين قصادهم رايات جديدة ووجوه جديدة، فتأكدوا فعلا إن المسلمين جالهم مدد بالليل فاتصدموا وبقت معنوياتهم في الأرض\n◇الخطوة الثالثة إللي عملها خالد بن الوليد:\nخلّى مجموعة من الجنود المسلمين في آخر الجيش على واحد من التلال الموجودة وراهم، وأمرهم إنهم ينتشروا  على مساحة عريضة، ودورهم إنهم يثيروا الغبار فقط،\nيعني يقعدوا يتحركوا في الأرض بالخيول فيتحرك التراب ويبقى في غبار في الجو،\nوالهدف من كده إنه يخدع الرومان ويخليهم يفكروا إن المدد إللي بييجي للمسلمين مستمر مش بينقطع،\nوالرومان شايفين الكلام ده وقلوبهم هتنخلع\n◇الخطوة الرابعة والأخيرة:\nخالد بن الوليد أمر المسلمين بالهجوم على الرومان وقتالهم، وفجأة أمر جيش المسلمين بالإنسحاب الكامل من أرض المعركة،\nفبدأ ينسحب بالجيش تدريجيا من قصاد الرومان إللي الصحراء في اتجاه المدينة،\nوالجيش الروماني واقف مبيتحركش من مكانه، لأنهم كانوا خايفين إن خالد كان بيسحبهم ويستدرجهم لكمين هو عامله في الصحراء،\nيعني إزاي ناس كانوا هاجمين علينا وقتلوا مننا كتير والمدد عمال يجيلهم وفجأة كده ينسحبوا،\nأكيد الموضوع وراه إنّ\nفمحدش فيهم تجرأ إنه يتبع خالد بن الوليد أو إنه يهاجم جيش المسلمين أو يتبعهم وفضلوا واقفين يتفرجوا على انسحاب خالد بن الوليد بالمسلمين من أرض المعركة\nومحدش من المسلمين تعرض لأي خطر خلال الانسحاب ده،\nوعلى فكرة لو مكنش الرومان شافوا قوة المسلمين والمسلمين نفسهم قتلوا منهم كتير مكنش الرومان سابوهم ينسحبوا وهم أعدادهم أكبر من المسلمين بأضعاف مضاعفة وكانوا طلعوا ورا المسلمين وقتلوهم وأسروا منهم وهم بينسحبوا\nده يمكن بالعكس ما صدقوا إنهم خلصوا من المسلمين إللي عمالين يقتلوا فيهم وهم مش عارفين يعملوا لهم حاجة\nووصل جيش المسلمين للمدينة بسلام وانتهت غزوة أو معركة مؤتة\n☆عندنا هنا بقى ثلاث نقط محتاجين نوضحهم،\n◇النقطة الأولى :\nالسرية بتتسمى سرية لأن رسول الله ﷺ مخرجش للقتال فيها،\nأما الغزوة هي إللي رسول الله ﷺ خرج للقتال فيها،\nلكن إللي شذ عن القاعدة دي هي غزوة مؤتة،\nيعني معركة مؤتة اشتهرت باسم غزوة مؤتة مع إن رسول الله ﷺ مخرجش فيها وده بسبب عِظَم شأن المعركة دي، وكثرة عددها،\nوحصول قتال عظيم فيها ، واهتمام رسول الله ﷺ بها لدرجة إنه خرج مع المسلمين لتوديع الجيش عند ثنية الوداع\n◇النقطة الثانية:\nالفرار أو الانسحاب من أرض المعركة كبيرة من الكبائر، يعني لو واحد بيجاهد وهو بيقاتل هرب فاللي عمله ده كبيرة من الكبائر اسمها الفرار من الزّحْف،\nوإللي يعمل الكبيرة دي جزاءه إن ربنا يغضب عليه ويدخله النار، طبعا إلا أن يشاء الله حاجة تانية،\nربنا قال:\n\" وَمَنْ يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُ إِلَّا مُتَحَرِّفًا لِقِتَالٍ أَوْ مُتَحَيِّزًا إِلَى فِئَةٍ فَقَدْ بَاءَ بِغَضَبٍ مِنَ اللَّهِ وَمَأْوَاهُ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ \"\nوزي ماحنا شايفين في استثناء في الآية، يعني ربنا بيحدد سببين للإنسحاب مش هيكون فيهم إثم أو حرام\n♧السبب الأول:\n إن المقاتل ينسحب بخطة حربية عشان يقدر يرجع للحرب من جديد.\n♧السبب الثاني:\nإن المقاتل أو الكتيبة ترجع للجيش الرئيسي عشان تتجهز أكثر ويرجعوا تاني للقتال، وهو ده إللي خالد بن الوليد رضي الله عنه عمله لما انسحب بالجيش،\nيعني جيش المسلمين هنا هو فرقة من المسلمين إللي جيشها الرئيسي أو الفئة بتاعته في المدينة،\nفهم رجعوا لفئة المسلمين الأكبر في المدينة عشان يتجهزوا ويكوّنوا جيش أكبر ويبقى يرجعوا بعدين لقتال الروم،\nوده إللي هنشوفه لما تيجي غزوة تبوك سنة تسعة من الهجرة، وساعتها جيش المسلمين هيكون ثلاثين ألف مقاتل\nفانسحاب الصحابة من أرض معركة مؤتة مكنش فيه أي خطأ شرعي، بالعكس ده كان هو الحل الصحيح،\nولما رجعوا للمدينة رسول الله ﷺ معاتبهمش ولا زجرهم ولا حتى أمرهم بالتوبة على اعتبار يعني إنهم أخطأوا، محصلش أي حاجة من دي، وزي ما قلنا رسول الله ﷺ مش هيسكت على منكر أو خطأ\n◇النقطة الثالثة بقى هي سؤال:\nهل معركة مؤتة تعتبر نصر ولّا هزيمة للمسلمين\nيعني هل جيش المسلمين انتصر ولا انهزم في معركة مؤتة؟!\nاختلف العلماء على ثلاثة أقوال، قول بيقول إن المسلمين اتهزموا في معركة مؤتة،\nوقول بيقول إن كان في تعادل بين الفريقين، يعني مفيش فريق منتصر ولا فريق منهزم،\nأما القول الثالث فهو إن المسلمين انتصروا على الرومان في معركة مؤتة وهو ده القول الراجح، وأنا شخصيا مقتنعة بيه، ليه\n◇أولا:\nفاكرين لما قلنا المرة إللي فاتت إن رسول الله ﷺ كان بيحكي إللي بيحصل في أرض المعركة للمسلمين في المدينة، وقال لهم:\n\" أخذ الراية زيد فأُصيب، ثم أخذها جعفر فأصيب، ثم أخذها ابن رواحة فأصيب، حتى أخذ الراية سيف من سيوف الله حتى فتح الله عليه\" والحديث ده في البخاري،\nفكلمة:《حتى فتح الله عليه》دي ملهاش معاني كتيرة، هو معنى واضح وصريح وهو النصر والفتح والعلو، لأن ربنا مش هيفتح عليهم بمجرد الانسحاب، لكن الواضح إن ربنا فتح على المسلمين بالنصر\nبدليل إن المسلمين في أرض المعركة كانت لهم اليد العليا وقتلوا أعداد كبيرة جدا من الرومان،\nالروايات بتقول إن عدد قتلى الرومان أكثر من ثلاثة آلاف،\nفي حين إن عدد قتلى المسلمين اثنا عشر رجل فقط،\nمتخيلين\nالمعركة دي بطولها وأعداد الرومان الكبيرة جدا دي ومقدروش يقتلوا غير اثنا عشر رجلا،\nفمستحيل يكون جيش مهزوم ويُقتل منه اثني عشر رجلاً فقط، في حين إن الرومان خسروا أضعاف العدد ده\nفإذا كان شهداء المسلمين أقل من قتلى الرومان فالعلامة دي من أقوى علامات النصر،\nفخالد لما شاف إن المسلمين حققوا نصر على جيش الرومان  اكتفى بالنصر ده وقرر الانسحاب لأنه كان واقعي جداً إلى أبعد درجة رضي الله عنه،\nفهو عارف إنه ميقدرش يتوغل في أرض الروم بالجيش الإسلامي الصغير ده، وإلا هيتحاصر ويُقتلوا جميعا\nوخدوا بالكم إن رسول الله ﷺ لو كان عايز يقول إنهم انسحبوا بس من غير انتصار كان قال كلمة تدل على المعنى ده، يعني كان يقول مثلا:\n《حتى أنجاهم الله》\nوهو ﷺ أبلغ البشر وأُوتي جوامع الكلام، ويقدر بكلمة واحدة إنه يوصف الحدث بالضبط زي ما تم في أرض مؤتة، فهو وصف إللي حصل فعلا وقال: \n《حتى فتح الله عليه》\n◇ثانيا:\nرسول الله ﷺ وهو بيحكي للمسلمين في المدينة عن القادة الثلاثة لما استشهدوا، كان رسول الله ﷺ بيقول للناس استغفروا لهم، يعني قال:\n \"ألا أخبركم عن جيشكم هذا الغازي؟ إنهم انطلقوا حتى لقوا العدو فأُصيب زيد شهيداً فاستغفروا له، فاستغفر له الناس\"\nفكان كل واحد ياخد الراية ويُقتل كان رسول الله ﷺ يقول للناس يستغفروا له، يعني يدعوا لهم بالمغفرة، ولما أخذ الراية خالد رفع رسول الله ﷺ إصبعيه وقال:\n \"اللهم هو سيف من سيوفك فانصره\"\nفده دعاء من رسول الله ﷺ لخالد بن الوليد وجيش المسلمين بالنصر ودعاء رسول الله ﷺ مستجاب،\nده غير كده رسول الله ﷺ كان قاعد بيحكي للمسلمين عن غيب محدش يعرفه من الموجودين فمستحيل يحصل عكس إللي رسول الله ﷺ بيقوله ودعا بيه\n◇ثالثا:\nالمسلمون أخذوا غنائم من معركة مؤتة، ولا يغنم إلا الجيش المنتصر، ومش بس كده ده في منهم غنموا ممتلكات بعض كبار القادة الرومانيين،\nيعني بعض المسلمين قتلوا بعض قادة الرومان وأخذوا أسلابهم، يعني سيوفهم أو السّرج إللي بيكون على الحصان، وكان السلاح والسّرج من الذهب\nفمين إللي هيمشي بالغنائم كده إلا لو كان منتصر\n ◇رابعا:\nبعد الغزوة محدش من شعراء المشركين قال شعر بيشمت فيه بهزيمة المسلمين في مؤتة وهم مش هيضيعوا فرصة زي دي أبدا،\nوعلى العكس بقى شعراء المسلمين كعب بن مالك وحسان بن ثابت قالوا شعر يفخروا فيه بالنصر على الجيش الروماني\n◇خامسا:\nمعركة مؤتة تركت أثر إيجابي كبير جدا على عرب الجزيرة خصوصا أهل المناطق الشمالية،\nوهنشوف بعدين إن بعد معركة مؤتة بدأت تيجي الوفود من القبائل إللي كانت دايما تحارب المسلمين عشان يعلنوا  إسلامهم عند رسول الله ﷺ، زي قبيلة غطفان إللي كان بينها وبين المسلمين غزوات وسرايا كتير واحنا شوفنا تاريخهم كان عامل إزاي،\nفالقبائل العربية بصفة عامة شافت إزاي المسلمين وقفوا أمام أعظم قوة في الأرض وانتصروا عليهم،\nولو كانت معركة مؤتة هزيمة للمسلمين مكنتش القبائل دي جت من الأساس، وكان راحوا يطلبوا وُدّ الرومان ويتقربوا لهم ويظهروا لهم الولاء، لكن ده محصلش\nولو كان في تعادل بين الجيشين، كانت قبائل العرب هتستنى لحد ما يشوفوا رد فعل الرومان هيكون إيه وبعدين يحددوا موقفهم،\nلكن مفيش حاجة من دي حصلت بالعكس ده راحوا لرسول الله ﷺ في المدينة ليُسلموا\nكل إللي احنا قلناه ده بيرد على الرواية الضعيفة إللي بتقول إن جيش المسلمين لما رجعوا للمدينة بعد معركة مؤتة أهل المدينة استقبلوهم بالحجارة وقعدوا يقولوا لهم :\n\"يا فُرّار، أَفررتم في سبيل الله\"\nيعني انتم سيبتم الجهاد في سبيل الله وهربتم، وطبعا ده مش صح زي ما شرحنا الأسباب ليه انسحابهم مكنش فرار وكمان كانوا جايين منتصرين،\nفالرواية إللي بتقول إن أهل المدينة استقبلوا المسلمين استقبال سيء غير صحيحة\nفنطلع بقى من الكلام إللي قلناه ده كله إن معركة مؤتة كانت انتصار حقيقي للمسلمين بكل المقاييس، وكان الانتصار ده له آثار إيجابية كبيرة ومَهّد لأحداث تانية هتحصل بعدين\nالمرة الجاية إن شاء الله هنرجع شوية بالزمن شوية عشان نتكلم عن أحداث داخلية حصلت في المدينة في نفس الوقت إللي كانت فيه السرايا خارجة للجهاد في سبيل الله"}]);
